;------------------------------------------------------------------------------
; SIDEWAYS ROM HEADER
;
; &8000  JMP terminal_entry   language entry. (TFS103.ROM has &00 here: BRK, which hangs *TELETEXT.)
; &8003  JMP service_entry    service entry
; &8006  &C2                  ROM type: service + language, 6502 code
; &8007  &11                  offset of the copyright string
; &8008  &01                  binary version number
; &8009  "TFS",0,"1.03",0     title (printed by the MOS when the language starts) and version
; &8011  0,"(C)1982 Acorn",0  copyright string the MOS checks for
;------------------------------------------------------------------------------
.L8000
    8000  4C 2F B3  JMP terminal_entry      ; language entry: start terminal mode
;------------------------------------------------------------------------------
; Service entry vector, ROM type, copyright offset, version, title and copyright strings.
;------------------------------------------------------------------------------
    8003  .db 4C 19 82 C2 11 01 54 46 53 00 31 2E 30 33 00 28  ; L.....TFS.1.03.(
    8013  .db 43 29 31 39 38 32 20 41 63 6F 72 6E 00           ; C)1982 Acorn.
;------------------------------------------------------------------------------
; HAMMING 8/4 DECODE TABLE (256 bytes), indexed by the received byte.
;
; Teletext protects addresses, page numbers and control bits with Hamming 8/4 coding:
; each byte carries 4 data bits plus 4 protection bits.
;   &0x  the byte was received cleanly; x is the decoded nibble
;   &4x  one bit was wrong and has been corrected; x is the nibble
;   &FF  two or more bits wrong: cannot be decoded
; hamming_decode_count (&90C1) also counts decodes and errors for the *TUNE meter.
;------------------------------------------------------------------------------
.hamming_table
    8020  .db 41 FF 01 41 FF 40 41 FF FF 42 41 FF 4A FF FF 47  ; A..A.@A..BA.J..G
    8030  .db FF 40 41 FF 40 00 FF 40 46 FF FF 4B FF 40 43 FF  ; .@A.@..@F..K.@C.
    8040  .db FF 4C 41 FF 44 FF FF 47 46 FF FF 47 FF 47 47 07  ; .LA.D..GF..G.GG.
    8050  .db 46 FF FF 45 FF 40 4D FF 06 46 46 FF 46 FF FF 47  ; F..E.@M..FF.F..G
    8060  .db FF 42 41 FF 44 FF FF 49 42 02 FF 42 FF 42 43 FF  ; .BA.D..IB..B.BC.
    8070  .db 48 FF FF 45 FF 40 43 FF FF 42 43 FF 43 FF 03 43  ; H..E.@C..BC.C..C
    8080  .db 44 FF FF 45 04 44 44 FF FF 42 4F FF 44 FF FF 47  ; D..E.DD..BO.D..G
    8090  .db FF 45 45 05 44 FF FF 45 46 FF FF 45 FF 4E 43 FF  ; .EE.D..EF..E.NC.
    80A0  .db FF 4C 41 FF 4A FF FF 49 4A FF FF 4B 0A 4A 4A FF  ; .LA.J..IJ..K.JJ.
    80B0  .db 48 FF FF 4B FF 40 4D FF FF 4B 4B 0B 4A FF FF 4B  ; H..K.@M..KK.J..K
    80C0  .db 4C 0C FF 4C FF 4C 4D FF FF 4C 4F FF 4A FF FF 47  ; L..L.LM..LO.J..G
    80D0  .db FF 4C 4D FF 4D FF 0D 4D 46 FF FF 4B FF 4E 4D FF  ; .LM.M..MF..K.NM.
    80E0  .db 48 FF FF 49 FF 49 49 09 FF 42 4F FF 4A FF FF 49  ; H..I.II..BO.J..I
    80F0  .db 08 48 48 FF 48 FF FF 49 48 FF FF 4B FF 4E 43 FF  ; .HH.H..IH..K.NC.
    8100  .db FF 4C 4F FF 44 FF FF 49 4F FF 0F 4F FF 4E 4F FF  ; .LO.D..IO..O.NO.
    8110  .db 48 FF FF 45 FF 4E 4D FF FF 4E 4F FF 4E 0E FF 4E  ; H..E.NM..NO.N..N
;------------------------------------------------------------------------------
; OSWORD &7A DISPATCH TABLE: 38 handler addresses for sub-commands &80-&A5.
; The first byte of the OSWORD parameter block selects the sub-command; see svc08_osword.
;------------------------------------------------------------------------------
.osword_table
    8120  .db F7 8B 46 8A 55 8A 64 8A 73 8A 00 98 F7 8B 36 A0  ; ..F.U.d.s.....6.
    8130  .db F7 8B 75 8B C8 8B 91 8A 84 81 97 92 86 92 F0 8A  ; ..u.............
    8140  .db 36 A0 D7 8A 82 8A CB 8A D6 95 05 8C 05 94 D7 81  ; 6...............
    8150  .db D7 81 D7 81 BA 8B 57 93 B4 92 E7 92 05 93 31 93  ; ......W.......1.
    8160  .db 93 96 0A 96 26 96 6C 81 71 96 82 96              ; ....&.l.q...
;------------------------------------------------------------------------------
; OSWORD &7A &A3: READ PAGE NUMBER
; Returns the seven digits of the current request slot (mag, tens, units, sub-code x4)
; as ASCII characters in bytes 1-7 of the parameter block.
;------------------------------------------------------------------------------
.osw_A3_read_page_number
    816C  A0 01     LDY #&01
    816E  AE 9B 0E  LDX cur_req             ; X = offset of the current request slot
.L8171
    8171  BD A2 0E  LDA req_mag,X
    8174  29 0F     AND #&0F                ; digit value is in the low nibble
    8176  18        CLC
    8177  69 30     ADC #&30                ; convert to ASCII
    8179  91 F0     STA (osw_x),Y
    817B  E8        INX
    817C  C8        INY
    817D  C0 08     CPY #&08
    817F  D0 F0     BNE L8171
    8181  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; OSWORD &7A &8C: READ PAGE FLAGS
; Returns in byte 1:  bit 7 = page carried a row 27 check word (req_s2 bit 6)
;                     bit 6 = computed checksum matched it   (req_s3 bit 6)
; Terminal mode uses this to show "Bad data" / "No check" on the status line.
;------------------------------------------------------------------------------
.osw_8C_read_page_flags
    8184  AE 9B 0E  LDX cur_req
    8187  BD A6 0E  LDA req_s2,X
    818A  29 40     AND #&40
    818C  0A        ASL A
    818D  85 BC     STA ptr
    818F  BD A7 0E  LDA req_s3,X
    8192  29 40     AND #&40
    8194  05 BC     ORA ptr
    8196  A0 01     LDY #&01
    8198  91 F0     STA (osw_x),Y
    819A  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; FILEV (OSFILE) for the Telesoft filing system.
;   A=5   read catalogue information  -> LAD1A
;   A=7   (create)                    -> LAC94
;   A=&FF load a file                 -> L9F4C
;   anything else: "Illegal operation" (TFS is read-only)
;------------------------------------------------------------------------------
.filev
    819D  C9 05     CMP #&05
    819F  F0 0B     BEQ L81AC
    81A1  C9 07     CMP #&07
    81A3  F0 0A     BEQ L81AF
    81A5  C9 FF     CMP #&FF
    81A7  D0 3D     BNE bputv_illegal
    81A9  4C 4C 9F  JMP L9F4C
.L81AC
    81AC  4C 1A AD  JMP LAD1A
.L81AF
    81AF  4C 94 AC  JMP LAC94
;------------------------------------------------------------------------------
; SERVICE CALL 8: UNRECOGNISED OSWORD
; Claims OSWORD &7A (the Teletext system call). The parameter block is at (osw_x).
; Sub-commands &80-&A5 dispatch through osword_table; codes below &80 go to LAD5A.
;------------------------------------------------------------------------------
.svc08_osword
    81B2  A5 EF     LDA osw_a               ; OSWORD number the MOS was given
    81B4  C9 7A     CMP #&7A                ; 'z'
    81B6  F0 03     BEQ L81BB
    81B8  4C 0B 82  JMP svc_exit_unclaimed
.L81BB
    81BB  A0 00     LDY #&00
    81BD  B1 F0     LDA (osw_x),Y           ; sub-command byte from the parameter block
    81BF  30 03     BMI L81C4
    81C1  4C 5A AD  JMP LAD5A
.L81C4
    81C4  0A        ASL A                   ; two bytes per table entry
    81C5  C9 4C     CMP #&4C                ; past &A5?
    81C7  B0 0E     BCS osw_bad
    81C9  AA        TAX
    81CA  BD 20 81  LDA osword_table,X
    81CD  85 BC     STA ptr
    81CF  BD 21 81  LDA &8121,X
    81D2  85 BD     STA ptr+1
    81D4  6C BC 00  JMP (ptr)               ; jump to the handler; handlers finish with JMP svc_exit_claimed
;------------------------------------------------------------------------------
; OSWORD &7A sub-commands &97-&99 and anything above &A5: "Bad OSWORD" (error &FF).
;------------------------------------------------------------------------------
.osw_bad
    81D7  20 98 A1  JSR error_inline
    81DA  .str '\xffBad OSWORD\x00'
;------------------------------------------------------------------------------
; BPUTV: the Telesoft filing system is read-only, so any write gives "Illegal operation".
;------------------------------------------------------------------------------
.bputv_illegal
    81E6  20 98 A1  JSR error_inline
    81E9  .str '\x9dIllegal operation\x00'
;------------------------------------------------------------------------------
; SERVICE CALL 4: UNRECOGNISED * COMMAND
; Looks the command up in the * command table (&9EE9). X=&4F is the table offset bias
; used by match_star_command. Carry set on return means the command was found and run.
;------------------------------------------------------------------------------
.svc04_star_command
    81FC  A5 F2     LDA text_ptr
    81FE  85 BC     STA ptr
    8200  A5 F3     LDA text_ptr+1
    8202  85 BD     STA ptr+1
    8204  A2 4F     LDX #&4F
    8206  20 87 9E  JSR match_star_command
    8209  B0 06     BCS svc_exit_claimed
;------------------------------------------------------------------------------
; Return from a service call WITHOUT claiming it: restore X, Y and A (the service number)
; from the frame pushed by service_entry.
;------------------------------------------------------------------------------
.svc_exit_unclaimed
    820B  68        PLA
    820C  AA        TAX
    820D  68        PLA
    820E  A8        TAY
    820F  68        PLA
    8210  60        RTS
;------------------------------------------------------------------------------
; Return from a service call CLAIMING it: restore X and Y, and return A=0.
;------------------------------------------------------------------------------
.svc_exit_claimed
    8211  68        PLA
    8212  AA        TAX
    8213  68        PLA
    8214  A8        TAY
    8215  68        PLA
    8216  A9 00     LDA #&00
    8218  60        RTS
;------------------------------------------------------------------------------
; PAGED ROM SERVICE ENTRY
;
; On entry A = service call number, X = this ROM's number, Y = parameter.
; A, Y and X are pushed so that every handler can reach them on the stack
; (&0103,X after TSX = the original A) and exit through svc_exit_claimed or
; svc_exit_unclaimed.
;
; Service 3 (auto-boot) is always handled so that "Acorn TFS / no power" can be
; printed. Every other service is ignored when the adapter is switched off: an
; unpowered adapter reads as zero in the link bits of TT_STATUS_CTRL, and then TFS
; claims no workspace and does nothing at all.
;------------------------------------------------------------------------------
.service_entry
    8219  48        PHA
    821A  98        TYA
    821B  48        PHA
    821C  8A        TXA
    821D  48        PHA
    821E  BA        TSX
    821F  BD 03 01  LDA &0103,X             ; A = service call number
    8222  C9 03     CMP #&03
    8224  D0 03     BNE L8229
    8226  4C B4 82  JMP svc03_autoboot
.L8229
    8229  AD 10 FC  LDA TT_STATUS_CTRL      ; link bits D3-D0 read 0 when the adapter has no power
    822C  29 0F     AND #&0F
    822E  F0 DB     BEQ svc_exit_unclaimed
    8230  BD 03 01  LDA &0103,X
    8233  C9 12     CMP #&12                ; service &12: select filing system
    8235  F0 0F     BEQ svc12_select_fs
    8237  C9 0B     CMP #&0B                ; only services 0-&0A are dispatched by table
    8239  B0 D0     BCS svc_exit_unclaimed
    823B  0A        ASL A
    823C  AA        TAX
    823D  BD 94 83  LDA &8394,X             ; RTS-dispatch: push handler address-1, then RTS
    8240  48        PHA
    8241  BD 93 83  LDA service_table,X
    8244  48        PHA
    8245  60        RTS
;------------------------------------------------------------------------------
; SERVICE CALL &12: SELECT FILING SYSTEM Y. TFS is filing system number 6.
;------------------------------------------------------------------------------
.svc12_select_fs
    8246  C0 06     CPY #&06
    8248  D0 C1     BNE svc_exit_unclaimed
    824A  20 34 9D  JSR cmd_TELESOFT
    824D  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; SERVICE CALL 1: ABSOLUTE WORKSPACE CLAIM
; Raise the claim so that pages &0E-&19 belong to the filing systems.
; Y is the highest page wanted so far; TFS needs it to be at least &1A.
; A is left as 1 so the call passes on to other ROMs.
;------------------------------------------------------------------------------
.svc01_abs_workspace
    8250  68        PLA
    8251  AA        TAX
    8252  68        PLA
    8253  A8        TAY
    8254  C0 1A     CPY #&1A
    8256  B0 02     BCS L825A
    8258  A0 1A     LDY #&1A
.L825A
    825A  68        PLA
    825B  60        RTS
;------------------------------------------------------------------------------
; SERVICE CALL 2: PRIVATE WORKSPACE CLAIM
; Y = first free private page. TFS takes 8 pages (2K) there and initialises its state:
;   - remember the private page in the MOS table at &0DF0+ROM number
;   - initialise the Telesoftware decoder tables (LA80A)
;   - clear all 25 request slots; slot 0 becomes the current page, using the private
;     workspace as its page buffer, and is marked active
;   - defaults: *OPT1,128  *OPT2,1  *OPT3,0, control latch &1C (capture on, IRQ on, AFC on, channel 1)
;   - immediately stash the static workspace (TFS is not the selected filing system yet)
; Returns Y = Y+8.
;------------------------------------------------------------------------------
.svc02_private_workspace
    825C  A6 F4     LDX romsel_copy
    825E  98        TYA
    825F  9D F0 0D  STA rom_wksp_table,X    ; private workspace page for this ROM
    8262  48        PHA
    8263  20 0A A8  JSR ts_init             ; initialise the Telesoftware name tables
    8266  A6 F4     LDX romsel_copy
    8268  8E 99 0E  STX prev_language       ; "previous language" defaults to this ROM
    826B  A2 F9     LDX #&F9
    826D  A9 00     LDA #&00
.L826F
    826F  9D A0 0E  STA req_buf,X           ; clear &0EA1-&0F99 (25 request slots of 10 bytes)
    8272  CA        DEX
    8273  D0 FA     BNE L826F
    8275  8D 9D 0E  STA hdr_dest+1
    8278  8D 9B 0E  STA cur_req
    827B  8D 9E 0E  STA &0E9E
    827E  8D 9F 0E  STA &0E9F
    8281  8D A0 0E  STA req_buf             ; slot 0 buffer = private workspace page, offset 0
    8284  68        PLA
    8285  48        PHA
    8286  8D A1 0E  STA req_buf+1
    8289  A9 40     LDA #&40                ; slot 0 is the active current-page request
    828B  8D A9 0E  STA req_state
    828E  A9 01     LDA #&01
    8290  8D 98 0E  STA opt2_errors         ; *OPT2,1: retry on checksum errors
    8293  A9 80     LDA #&80
    8295  20 7C AC  JSR LAC7C               ; *OPT1,128
    8298  A9 00     LDA #&00
    829A  20 80 AC  JSR LAC80               ; *OPT3,0
    829D  A9 01     LDA #&01
    829F  8D 5D 0E  STA tsdp+1
    82A2  A9 1C     LDA #&1C
    82A4  8D 8E 0E  STA ctrl_shadow         ; TT_STATUS_CTRL shadow: b4 AFC on, b3 IRQ enable, b2 capture enable, channel 0
    82A7  68        PLA
    82A8  20 46 83  JSR stash_workspace     ; save the static workspace in the adapter RAM and private workspace
    82AB  68        PLA
    82AC  AA        TAX
    82AD  68        PLA
    82AE  18        CLC
    82AF  69 08     ADC #&08                ; claim 8 pages
    82B1  A8        TAY
    82B2  68        PLA
    82B3  60        RTS
;------------------------------------------------------------------------------
; SERVICE CALL 3: AUTO-BOOT
; Runs after BREAK. If no key is held, or T is held (internal key number &23),
; print "Acorn TFS" and make Telesoft the filing system.
; If the adapter has no power, print "no power" instead and claim nothing else.
; Any other key held: pass the call on so that another filing system can boot.
; The keyboard buffer is flushed and &CA re-inserted: &CA is the code that makes the
; MOS run the *KEY10 string after BREAK. OSBYTE &78 records T as the key being held so
; the T used for T+BREAK does not also appear as a typed character.
;------------------------------------------------------------------------------
.svc03_autoboot
    82B4  A9 7A     LDA #&7A
    82B6  20 F4 FF  JSR OSBYTE              ; OSBYTE &7A: keyboard scan from key 16
    82B9  8A        TXA
    82BA  C9 FF     CMP #&FF
    82BC  F0 04     BEQ L82C2
    82BE  C9 23     CMP #&23                ; internal key number for T
    82C0  D0 6B     BNE L832D
.L82C2
    82C2  20 AF A2  JSR print_inline
    82C5  .str 'Acorn TFS\x00'
    82CF  AD 10 FC  LDA TT_STATUS_CTRL      ; adapter powered?
    82D2  29 0F     AND #&0F
    82D4  D0 2F     BNE L8305
    82D6  20 AF A2  JSR print_inline
    82D9  .str '  no power\r\n\n\x00'
    82E7  A9 15     LDA #&15
    82E9  A2 00     LDX #&00
    82EB  A0 00     LDY #&00
    82ED  20 F4 FF  JSR OSBYTE              ; OSBYTE &15: flush buffer X
    82F0  A9 8A     LDA #&8A
    82F2  A2 00     LDX #&00
    82F4  A0 CA     LDY #&CA
    82F6  20 F4 FF  JSR OSBYTE              ; OSBYTE &8A: insert character into buffer
    82F9  A9 78     LDA #&78
    82FB  A2 23     LDX #&23
    82FD  A0 00     LDY #&00
    82FF  20 F4 FF  JSR OSBYTE              ; OSBYTE &78: write keys-pressed information
    8302  4C 11 82  JMP svc_exit_claimed    ; claim the call: no other ROM boots
.L8305
    8305  20 AF A2  JSR print_inline
    8308  .str '\r\n\n\x00'
    830C  20 34 9D  JSR cmd_TELESOFT        ; select Telesoft (TFS) as the filing system
    830F  A9 15     LDA #&15
    8311  A2 00     LDX #&00
    8313  A0 00     LDY #&00
    8315  20 F4 FF  JSR OSBYTE              ; OSBYTE &15: flush buffer X
    8318  A9 8A     LDA #&8A
    831A  A2 00     LDX #&00
    831C  A0 CA     LDY #&CA
    831E  20 F4 FF  JSR OSBYTE              ; OSBYTE &8A: insert character into buffer
    8321  A9 78     LDA #&78
    8323  A2 23     LDX #&23
    8325  A0 00     LDY #&00
    8327  20 F4 FF  JSR OSBYTE              ; OSBYTE &78: write keys-pressed information
    832A  4C 11 82  JMP svc_exit_claimed
.L832D
    832D  4C 0B 82  JMP svc_exit_unclaimed
;------------------------------------------------------------------------------
; SERVICE CALL 9: *HELP. Handled by help_command; the call is always passed on.
;------------------------------------------------------------------------------
.svc09_help
    8330  20 C3 83  JSR help_command
    8333  4C 0B 82  JMP svc_exit_unclaimed
;------------------------------------------------------------------------------
; SERVICE CALL &0A: ANOTHER ROM WANTS THE STATIC WORKSPACE
; If TFS's state isn't already stashed (bit 7 of its &0DF0 entry clear), stash it now.
;------------------------------------------------------------------------------
.svc0A_static_workspace
    8336  A6 F4     LDX romsel_copy
    8338  BD F0 0D  LDA rom_wksp_table,X
    833B  10 03     BPL L8340
    833D  4C 0B 82  JMP svc_exit_unclaimed
.L8340
    8340  20 46 83  JSR stash_workspace
    8343  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; STASH TFS STATE (A = private workspace page)
;
; The filing systems share &0E00-&19FF, so TFS must save its state when another
; filing system takes over. It saves 3K starting at &0E8E:
;   - the first 1K (&0E8E-&128D) goes into the ADAPTER'S OWN 1K RAM, 64 bytes into each
;     of the 16 line slots (capture is switched off first so the hardware can't overwrite it)
;   - the next 2K (&128E-&1A8D) goes to the 8 pages of private workspace
; Bit 7 of the &0DF0 entry marks the state as stashed; cmd_TELESOFT reverses this.
; NOTE: 3K from &0E8E ends at &1A8D, so the last 142 bytes come from &1A00-&1A8D,
; above the claimed workspace (normally the start of user memory). See cmd_TELESOFT.
;------------------------------------------------------------------------------
.stash_workspace
    8346  A6 F4     LDX romsel_copy
    8348  85 C1     STA ptr2+1
    834A  09 80     ORA #&80                ; mark "state stashed"
    834C  9D F0 0D  STA rom_wksp_table,X
    834F  29 7F     AND #&7F
    8351  20 49 A2  JSR capture_off         ; stop capture and IRQs so the adapter RAM is free
    8354  08        PHP
    8355  78        SEI
    8356  A9 8E     LDA #&8E
    8358  85 BC     STA ptr
    835A  A9 0E     LDA #&0E
    835C  85 BD     STA ptr+1
    835E  A2 0F     LDX #&0F                ; 16 slots
.L8360
    8360  A0 3F     LDY #&3F                ; 64 bytes per slot
    8362  8E 11 FC  STX TT_SLOT             ; select adapter RAM slot X (resets its byte counter)
.L8365
    8365  B1 BC     LDA (ptr),Y
    8367  8D 12 FC  STA TT_DATA             ; write one byte; the address counter steps on
    836A  88        DEY
    836B  10 F8     BPL L8365
    836D  A5 BC     LDA ptr
    836F  18        CLC
    8370  69 40     ADC #&40
    8372  85 BC     STA ptr
    8374  90 02     BCC L8378
    8376  E6 BD     INC ptr+1
.L8378
    8378  CA        DEX
    8379  10 E5     BPL L8360
    837B  A9 00     LDA #&00
    837D  85 C0     STA ptr2
    837F  A2 07     LDX #&07                ; 8 pages to private workspace
.L8381
    8381  A0 00     LDY #&00
.L8383
    8383  B1 BC     LDA (ptr),Y
    8385  91 C0     STA (ptr2),Y
    8387  C8        INY
    8388  D0 F9     BNE L8383
    838A  E6 BD     INC ptr+1
    838C  E6 C1     INC ptr2+1
    838E  CA        DEX
    838F  10 F0     BPL L8381
    8391  28        PLP
    8392  60        RTS
;------------------------------------------------------------------------------
; SERVICE CALL DISPATCH TABLE (address-1 for RTS dispatch), services 0-&0A:
; 0 none, 1 abs workspace, 2 private workspace, 3 auto-boot, 4 * command,
; 5 interrupt, 6 BRK (ignored), 7 OSBYTE (ignored), 8 OSWORD, 9 *HELP, &0A static workspace.
;------------------------------------------------------------------------------
.service_table
    8393  .db 0A 82 4F 82 5B 82 B3 82 FB 81 3E 8D 0A 82 0A 82  ; ..O.[.....>.....
    83A3  .db B1 81 2F 83 35 83                                ; ../.5.
;------------------------------------------------------------------------------
; BGETV (OSBGET). Y = channel.
;   channel 15: read the next character of the current Teletext page (L9510)
;   channel 14: read the next byte of a decoded Telesoftware file (LABD1)
;   anything else: "Channel" error
;------------------------------------------------------------------------------
.bgetv
    83A9  C0 0F     CPY #&0F
    83AB  F0 07     BEQ L83B4
    83AD  C0 0E     CPY #&0E
    83AF  D0 06     BNE L83B7
    83B1  4C D1 AB  JMP LABD1
.L83B4
    83B4  4C 10 95  JMP L9510
.L83B7
    83B7  20 98 A1  JSR error_inline
    83BA  .str '\xdeChannel\x00'
;------------------------------------------------------------------------------
; *HELP handler. With no keyword, prints the ROM title and version and the list of
; keywords (TELETEXT, TELESOFT, OPT). With a keyword (abbreviations with "." allowed),
; prints the matching help text from &84FF / &872C / &895A.
; text_ptr is preserved for the other ROMs that also see the *HELP.
;------------------------------------------------------------------------------
.help_command
    83C3  98        TYA
    83C4  48        PHA
    83C5  8A        TXA
    83C6  48        PHA
    83C7  A5 F2     LDA text_ptr
    83C9  48        PHA
    83CA  A5 F3     LDA text_ptr+1
    83CC  48        PHA
    83CD  20 5B 84  JSR L845B               ; skip "HELP" (Y = offset past the command name)
.L83D0
    83D0  A0 00     LDY #&00
    83D2  B1 F2     LDA (text_ptr),Y
    83D4  C9 0D     CMP #&0D
    83D6  F0 2F     BEQ L8407
    83D8  C9 20     CMP #&20
    83DA  D0 08     BNE L83E4
    83DC  E6 F2     INC text_ptr
    83DE  D0 F0     BNE L83D0
    83E0  E6 F3     INC text_ptr+1
    83E2  D0 EC     BNE L83D0
.L83E4
    83E4  20 66 84  JSR L8466               ; look the word up in the keyword table
    83E7  B0 05     BCS L83EE
    83E9  20 C8 84  JSR L84C8
    83EC  A0 00     LDY #&00
.L83EE
    83EE  B1 F2     LDA (text_ptr),Y
    83F0  C9 0D     CMP #&0D
    83F2  F0 5C     BEQ L8450
    83F4  C9 20     CMP #&20
    83F6  F0 08     BEQ L8400
    83F8  C9 2E     CMP #&2E                ; '.'
    83FA  F0 04     BEQ L8400
    83FC  C8        INY
    83FD  4C EE 83  JMP L83EE
.L8400
    8400  C8        INY
    8401  20 5B 84  JSR L845B
    8404  4C E4 83  JMP L83E4
.L8407
    8407  20 E7 FF  JSR OSNEWL              ; plain *HELP: print the title and version from the ROM header
    840A  A9 09     LDA #&09
    840C  85 BC     STA ptr
    840E  A9 80     LDA #&80
    8410  85 BD     STA ptr+1
    8412  20 C8 84  JSR L84C8
    8415  A9 20     LDA #&20
    8417  20 EE FF  JSR OSWRCH              ; print ' '
    841A  C8        INY
    841B  20 C8 84  JSR L84C8
    841E  20 E7 FF  JSR OSNEWL
    8421  A9 D9     LDA #&D9                ; then the keyword list at &84D9
    8423  85 BC     STA ptr
    8425  A9 84     LDA #&84
    8427  85 BD     STA ptr+1
    8429  A0 00     LDY #&00
    842B  20 C8 84  JSR L84C8
    842E  A2 01     LDX #&01
.L8430
    8430  E0 03     CPX #&03
    8432  B0 17     BCS L844B
    8434  A9 0A     LDA #&0A
    8436  20 EE FF  JSR OSWRCH              ; VDU 10: line feed
    8439  A9 20     LDA #&20
    843B  20 EE FF  JSR OSWRCH              ; print ' '
    843E  20 EE FF  JSR OSWRCH
    8441  C8        INY
    8442  C8        INY
    8443  C8        INY
    8444  20 C8 84  JSR L84C8
    8447  E8        INX
    8448  4C 30 84  JMP L8430
.L844B
    844B  A9 0A     LDA #&0A
    844D  20 EE FF  JSR OSWRCH              ; VDU 10: line feed
.L8450
    8450  68        PLA
    8451  85 F3     STA text_ptr+1
    8453  68        PLA
    8454  85 F2     STA text_ptr
    8456  68        PLA
    8457  AA        TAX
    8458  68        PLA
    8459  A8        TAY
    845A  60        RTS
; text_ptr += Y
.L845B
    845B  98        TYA
    845C  18        CLC
    845D  65 F2     ADC text_ptr
    845F  85 F2     STA text_ptr
    8461  90 02     BCC L8465
    8463  E6 F3     INC text_ptr+1
.L8465
    8465  60        RTS
;------------------------------------------------------------------------------
; Match the word at (text_ptr) against the *HELP keyword table at &84DB (each entry is
; a word, CR, 0, then a 2-byte text address). Returns C clear and (ptr) = the help text
; on a match, C set (and text_ptr past the word) if nothing matches.
;------------------------------------------------------------------------------
.L8466
    8466  A9 DB     LDA #&DB
    8468  85 BC     STA ptr
    846A  A9 84     LDA #&84
    846C  85 BD     STA ptr+1
    846E  A2 01     LDX #&01
