    847E  E9 20     SBC #&20
    8480  D1 BC     CMP (ptr),Y
    8482  F0 17     BEQ L849B
    8484  C9 00     CMP #&00
    8486  D0 06     BNE L848E
    8488  B1 BC     LDA (ptr),Y
    848A  C9 0D     CMP #&0D
    848C  F0 11     BEQ L849F
.L848E
    848E  E0 03     CPX #&03
    8490  B0 25     BCS L84B7
    8492  E8        INX
    8493  A9 0C     LDA #&0C
    8495  20 BE 84  JSR L84BE
    8498  4C 70 84  JMP L8470
.L849B
    849B  C9 0D     CMP #&0D
    849D  D0 D3     BNE L8472
.L849F
    849F  20 5B 84  JSR L845B
    84A2  A9 0A     LDA #&0A
    84A4  20 BE 84  JSR L84BE
    84A7  A0 00     LDY #&00
    84A9  B1 BC     LDA (ptr),Y
    84AB  48        PHA
    84AC  C8        INY
    84AD  B1 BC     LDA (ptr),Y
    84AF  85 BD     STA ptr+1
    84B1  68        PLA
    84B2  85 BC     STA ptr
    84B4  18        CLC
    84B5  90 04     BCC L84BB
.L84B7
    84B7  20 5B 84  JSR L845B
    84BA  38        SEC
.L84BB
    84BB  A0 00     LDY #&00
    84BD  60        RTS
.L84BE
    84BE  18        CLC
    84BF  65 BC     ADC ptr
    84C1  85 BC     STA ptr
    84C3  90 02     BCC L84C7
    84C5  E6 BD     INC ptr+1
.L84C7
    84C7  60        RTS
