;------------------------------------------------------------------------------
; OSWORD &7A &81-&84: PAGE READ-POSITION BOOKKEEPING
; BGET on channel 15 reads the current page character by character, from position
; (rd_row, rd_col). The Telesoftware decoder uses these calls to remember and return to
; positions while it parses a block:
;   &84  mark  := current position
;   &81  start := mark
;   &82  current position := start (rewind)
;   &83  limit := mark (BGET reports end of data at the limit)
;------------------------------------------------------------------------------
.osw_81_start_from_mark
    8A46  AD 91 0E  LDA rd_mark_row
    8A49  8D 93 0E  STA rd_start_row
    8A4C  AD 92 0E  LDA rd_mark_col
    8A4F  8D 94 0E  STA rd_start_col
    8A52  4C 11 82  JMP svc_exit_claimed
.osw_82_rewind_to_start
    8A55  AD 93 0E  LDA rd_start_row
    8A58  8D 8F 0E  STA rd_row
    8A5B  AD 94 0E  LDA rd_start_col
    8A5E  8D 90 0E  STA rd_col
    8A61  4C 11 82  JMP svc_exit_claimed
.osw_83_limit_at_mark
    8A64  AD 91 0E  LDA rd_mark_row
    8A67  8D 95 0E  STA rd_limit_row
    8A6A  AD 92 0E  LDA rd_mark_col
    8A6D  8D 96 0E  STA rd_limit_col
    8A70  4C 11 82  JMP svc_exit_claimed
.osw_84_mark_position
    8A73  AD 8F 0E  LDA rd_row
    8A76  8D 91 0E  STA rd_mark_row
    8A79  AD 90 0E  LDA rd_col
    8A7C  8D 92 0E  STA rd_mark_col
    8A7F  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; OSWORD &7A &92: HEADERS [&92, addr lo, addr hi]
; Store the address where the interrupt handler writes the 32 rolling header characters
; of every row 0 received (hdr_dest; 0 = off). Note bytes 1-2 land in hdr_dest via
; &0E9B+Y, Y=1..2.
;------------------------------------------------------------------------------
.osw_92_headers
    8A82  A0 01     LDY #&01
.L8A84
    8A84  B1 F0     LDA (osw_x),Y
    8A86  99 9B 0E  STA cur_req,Y
    8A89  C8        INY
    8A8A  C0 03     CPY #&03
    8A8C  D0 F6     BNE L8A84
    8A8E  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; OSWORD &7A &8B: SELECT CHANNEL [&8B, channel 0-3]
; Writes the channel number into bits 0-1 of the control latch: IC6b decodes them and
; one of Q3-Q6 connects tuning preset VR2-VR5. All captures in progress are abandoned
; and every magazine is marked idle, because rows from the old channel are useless.
;------------------------------------------------------------------------------
.osw_8B_select_channel
    8A91  A0 01     LDY #&01
    8A93  B1 F0     LDA (osw_x),Y
.L8A95
    8A95  4D 8E 0E  EOR ctrl_shadow         ; merge the new channel into bits 0-1 of the shadow
    8A98  29 03     AND #&03
    8A9A  4D 8E 0E  EOR ctrl_shadow
    8A9D  8D 8E 0E  STA ctrl_shadow
    8AA0  8D 10 FC  STA TT_STATUS_CTRL      ; select the tuning preset
    8AA3  A9 01     LDA #&01                ; reset the broadcast-data packet (no time/date yet)
    8AA5  8D 5D 0E  STA tsdp+1
    8AA8  A2 00     LDX #&00
.L8AAA
    8AAA  8A        TXA
    8AAB  48        PHA
    8AAC  BD A9 0E  LDA req_state,X         ; active request slot?
    8AAF  2A        ROL A
    8AB0  10 03     BPL L8AB5
    8AB2  20 A2 90  JSR clear_capture_flags ; abandon any capture in progress for it
.L8AB5
    8AB5  68        PLA
    8AB6  18        CLC
    8AB7  69 0A     ADC #&0A
    8AB9  AA        TAX
    8ABA  C9 FA     CMP #&FA
    8ABC  D0 EC     BNE L8AAA
    8ABE  A9 FF     LDA #&FF
    8AC0  A2 07     LDX #&07
.L8AC2
    8AC2  9D 15 0E  STA mag_capture,X       ; no page being captured in any magazine
    8AC5  CA        DEX
    8AC6  10 FA     BPL L8AC2
    8AC8  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; OSWORD &7A &93: WHAT CHANNEL. Returns bits 0-1 of the control latch in byte 1.
;------------------------------------------------------------------------------
.osw_93_what_channel
    8ACB  A0 01     LDY #&01
    8ACD  AD 8E 0E  LDA ctrl_shadow
    8AD0  29 03     AND #&03
    8AD2  91 F0     STA (osw_x),Y
    8AD4  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; OSWORD &7A &91: READ PREVIOUS LANGUAGE AND FILING SYSTEM
; Byte 1 = language ROM that was running before *TELETEXT (for f9),
; byte 2 = filing system number that was selected before *TELESOFT.
;------------------------------------------------------------------------------
.osw_91_read_prev_lang
    8AD7  A0 01     LDY #&01
    8AD9  AD 99 0E  LDA prev_language
    8ADC  91 F0     STA (osw_x),Y
    8ADE  C8        INY
    8ADF  AD 9A 0E  LDA prev_fs
    8AE2  91 F0     STA (osw_x),Y
    8AE4  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; Return A to the caller of a BGET-style routine: restore X and Y from the stack.
;------------------------------------------------------------------------------
.L8AE7
    8AE7  85 BC     STA ptr
    8AE9  68        PLA
    8AEA  AA        TAX
    8AEB  68        PLA
    8AEC  A8        TAY
    8AED  A5 BC     LDA ptr
    8AEF  60        RTS
;------------------------------------------------------------------------------
; OSWORD &7A &8F: TRANSFER [&8F, 32-bit address]
; Wait for the current page to arrive (or ESCAPE), then copy it to the address given,
; as 24 rows x 40 characters (960 bytes) of MODE 7 screen codes:
;   - every character has bit 7 set, so control codes &00-&1F become the MODE 7 teletext
;     control codes &80-&9F
;   - rows that never arrived are filled with spaces
;   - a row containing "double height" (&8D) is written twice and the next transmitted
;     row is skipped, which is how double height works on a teletext screen
; The address may be in a second processor: LA28C writes through the Tube when needed.
; The page is unlocked afterwards.
;------------------------------------------------------------------------------
.osw_8F_transfer
    8AF0  A5 F0     LDA osw_x               ; point ptr at the 4-byte address in the parameter block
    8AF2  18        CLC
    8AF3  69 01     ADC #&01
    8AF5  85 BC     STA ptr
    8AF7  A5 F1     LDA osw_y
    8AF9  69 00     ADC #&00
    8AFB  85 BD     STA ptr+1
    8AFD  20 76 A2  JSR LA276               ; copy the destination address to ptr2..&C3 and set up Tube transfer if needed
    8B00  A5 EF     LDA osw_a
    8B02  48        PHA
    8B03  A5 F0     LDA osw_x
    8B05  48        PHA
    8B06  A5 F1     LDA osw_y
    8B08  48        PHA
    8B09  08        PHP
    8B0A  58        CLI
    8B0B  AE 9B 0E  LDX cur_req             ; X = current request slot
    8B0E  BD A0 0E  LDA req_buf,X
    8B11  85 BC     STA ptr
    8B13  BD A1 0E  LDA req_buf+1,X
    8B16  85 BD     STA ptr+1
    8B18  20 2B 8C  JSR L8C2B               ; wait until the page has arrived, then lock it
    8B1B  24 FF     BIT escape_flag
    8B1D  30 2F     BMI L8B4E
    8B1F  A2 18     LDX #&18                ; 24 rows
    8B21  A9 00     LDA #&00
    8B23  85 B0     STA zp_b0               ; zp_b0 = double-height state
.L8B25
    8B25  A0 02     LDY #&02                ; row tag: &FF means the row was never received
    8B27  B1 BC     LDA (ptr),Y
    8B29  10 0C     BPL L8B37
    8B2B  A0 28     LDY #&28                ; write 40 spaces instead
    8B2D  A9 20     LDA #&20
.L8B2F
    8B2F  20 8C A2  JSR LA28C
    8B32  88        DEY
    8B33  D0 FA     BNE L8B2F
    8B35  F0 14     BEQ L8B4B
.L8B37
    8B37  A0 0A     LDY #&0A                ; characters are at offsets 10-49 of a row record
.L8B39
    8B39  B1 BC     LDA (ptr),Y
    8B3B  09 80     ORA #&80                ; make it a MODE 7 code
    8B3D  20 8C A2  JSR LA28C
    8B40  C9 8D     CMP #&8D                ; double height in this row?
    8B42  D0 02     BNE L8B46
    8B44  E6 B0     INC zp_b0
.L8B46
    8B46  C8        INY
    8B47  C0 32     CPY #&32                ; '2'
    8B49  D0 EE     BNE L8B39
.L8B4B
    8B4B  CA        DEX
    8B4C  D0 0D     BNE L8B5B
.L8B4E
    8B4E  28        PLP
    8B4F  68        PLA
    8B50  85 F1     STA osw_y
    8B52  68        PLA
    8B53  85 F0     STA osw_x
    8B55  68        PLA
    8B56  85 EF     STA osw_a
    8B58  4C C8 8B  JMP osw_8A_unlock
.L8B5B
    8B5B  A5 B0     LDA zp_b0               ; double-height state machine
    8B5D  F0 0E     BEQ L8B6D
    8B5F  49 80     EOR #&80
    8B61  85 B0     STA zp_b0
    8B63  30 C0     BMI L8B25               ; first pass: send the same row again
    8B65  A9 00     LDA #&00
    8B67  85 B0     STA zp_b0
    8B69  A9 02     LDA #&02                ; second pass done: skip the transmitted copy of the next row
    8B6B  D0 02     BNE L8B6F
.L8B6D
    8B6D  A9 01     LDA #&01                ; normal: advance one row record
.L8B6F
    8B6F  20 1C 8D  JSR row_offset          ; ptr += A * 48 (row records are 48 bytes apart)
    8B72  4C 25 8B  JMP L8B25
;------------------------------------------------------------------------------
; OSWORD &7A &89: TEST ARRIVED [&89, result]
; Result &FF if a new copy of the current page has arrived (and is complete), else 0.
; On success the page is LOCKED so that the interrupt handler won't overwrite it while
; it is read; UNLOCK (&8A) or TRANSFER releases it.
;
; REQUEST SLOTS: 25 slots of 10 bytes at &0EA0. Slot 0 is the current page; the others
; hold kept pages and pages prefetched through links. cur_req selects the slot OSWORD
; calls act on, but this version only ever sets it to 0.
;   +0,+1  page buffer address      +2..+8  page digits: mag, tens, units, sub-code x4
;   +9     state: &40 = active      (digits: bits 0-3 value, bit 7 = wild)
; Status bits are kept in bit 6 of the digit bytes:
;   req_mag  b6  LOCKED       req_s1  b6  VALID (a complete copy is in the buffer)
;   req_tens b6  ARRIVED      req_s2  b6  CHECK WORD present
;   req_units b6 CAPTURING    req_s3  b6  CHECKSUM OK
;                             req_s4  b6  KEPT (f3)
;------------------------------------------------------------------------------
.osw_89_test_arrived
    8B75  AE 9B 0E  LDX cur_req
    8B78  BD A3 0E  LDA req_tens,X          ; new arrival?
    8B7B  2A        ROL A
    8B7C  10 33     BPL L8BB1
    8B7E  BD A2 0E  LDA req_mag,X
    8B81  09 40     ORA #&40                ; lock it
    8B83  9D A2 0E  STA req_mag,X
    8B86  BD A4 0E  LDA req_units,X         ; capture of a newer copy already started?
    8B89  2A        ROL A
    8B8A  30 1D     BMI L8BA9
    8B8C  BD A3 0E  LDA req_tens,X
    8B8F  2A        ROL A
    8B90  10 17     BPL L8BA9               ; (re-test after locking)
    8B92  BD A3 0E  LDA req_tens,X          ; consume the "arrived" event
    8B95  29 BF     AND #&BF
    8B97  9D A3 0E  STA req_tens,X
    8B9A  BD A5 0E  LDA req_s1,X            ; complete copy available?
    8B9D  2A        ROL A
    8B9E  10 11     BPL L8BB1
    8BA0  A0 01     LDY #&01
    8BA2  A9 FF     LDA #&FF
    8BA4  91 F0     STA (osw_x),Y
    8BA6  4C 11 82  JMP svc_exit_claimed
.L8BA9
    8BA9  BD A2 0E  LDA req_mag,X
    8BAC  29 BF     AND #&BF
    8BAE  9D A2 0E  STA req_mag,X
.L8BB1
    8BB1  A0 01     LDY #&01
    8BB3  A9 00     LDA #&00
    8BB5  91 F0     STA (osw_x),Y
    8BB7  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; OSWORD &7A &9A: UNLOCK and also forget that the buffer holds a valid page.
;------------------------------------------------------------------------------
.osw_9A_unlock_variant
    8BBA  20 CE 8B  JSR unlock_current
    8BBD  BD A5 0E  LDA req_s1,X
    8BC0  29 BF     AND #&BF
    8BC2  9D A5 0E  STA req_s1,X
    8BC5  4C 11 82  JMP svc_exit_claimed
; OSWORD &7A &8A: UNLOCK PAGE
.osw_8A_unlock
    8BC8  20 CE 8B  JSR unlock_current
    8BCB  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; Clear LOCKED and ARRIVED on the current slot. If a capture was in progress the copy in
; the buffer is incomplete, so VALID and CAPTURING are cleared too.
;------------------------------------------------------------------------------
.unlock_current
    8BCE  AE 9B 0E  LDX cur_req
    8BD1  BD A3 0E  LDA req_tens,X
    8BD4  29 BF     AND #&BF
    8BD6  9D A3 0E  STA req_tens,X
    8BD9  BD A4 0E  LDA req_units,X
    8BDC  48        PHA
    8BDD  29 BF     AND #&BF
    8BDF  9D A4 0E  STA req_units,X
    8BE2  68        PLA
    8BE3  2A        ROL A
    8BE4  10 08     BPL L8BEE
    8BE6  BD A5 0E  LDA req_s1,X
    8BE9  29 BF     AND #&BF
    8BEB  9D A5 0E  STA req_s1,X
.L8BEE
    8BEE  BD A2 0E  LDA req_mag,X
    8BF1  29 BF     AND #&BF
    8BF3  9D A2 0E  STA req_mag,X
    8BF6  60        RTS
;------------------------------------------------------------------------------
; OSWORD &7A &80 RELOAD, &86 CHAINED PAGE, &88 HEAD OF CHAIN
; In this version all three share one implementation: follow link 0 of the current
; page's row 27 (L9420 with A=0), request that page, and wait for it.
;
; Stack trick: &8C04 is pushed as a return address and three zeros as a dummy
; service-call frame. L9420 eventually leaves through svc_exit_claimed, which pops the
; dummy frame and "returns" to &8C05 (osw_95_internal) to wait for the page; that then
; exits through the real frame.
;------------------------------------------------------------------------------
.osw_80_86_88_reload_chain
    8BF7  A9 8C     LDA #&8C
    8BF9  48        PHA
    8BFA  A9 04     LDA #&04
    8BFC  48        PHA
    8BFD  A9 00     LDA #&00
    8BFF  48        PHA
    8C00  48        PHA
    8C01  48        PHA
    8C02  4C 20 94  JMP L9420
;------------------------------------------------------------------------------
; OSWORD &7A &95: WAIT FOR PAGE (with checksum handling)
; Reset the read position, then wait for the current page to arrive, honouring *OPT2.
; Interrupts are enabled while waiting.
;------------------------------------------------------------------------------
.osw_95_wait_page
    8C05  20 E8 97  JSR reset_read_position
    8C08  A5 EF     LDA osw_a
    8C0A  48        PHA
    8C0B  A5 F0     LDA osw_x
    8C0D  48        PHA
    8C0E  A5 F1     LDA osw_y
    8C10  48        PHA
    8C11  08        PHP
    8C12  58        CLI
    8C13  20 C7 8C  JSR L8CC7
    8C16  28        PLP
    8C17  68        PLA
    8C18  85 F1     STA osw_y
    8C1A  68        PLA
    8C1B  85 F0     STA osw_x
    8C1D  68        PLA
    8C1E  85 EF     STA osw_a
    8C20  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; Wait for the current page: loop until VALID, lock it, wait for any capture in progress
; to finish, and retry if the copy was invalidated meanwhile. ESCAPE aborts.
;------------------------------------------------------------------------------
.L8C23
    8C23  BD A2 0E  LDA req_mag,X
    8C26  29 BF     AND #&BF
    8C28  9D A2 0E  STA req_mag,X
.L8C2B
    8C2B  24 FF     BIT escape_flag
    8C2D  30 21     BMI L8C50
    8C2F  AE 9B 0E  LDX cur_req
    8C32  BD A5 0E  LDA req_s1,X
    8C35  2A        ROL A
    8C36  10 F3     BPL L8C2B
    8C38  BD A2 0E  LDA req_mag,X
    8C3B  09 40     ORA #&40
    8C3D  9D A2 0E  STA req_mag,X
.L8C40
    8C40  24 FF     BIT escape_flag
    8C42  30 0C     BMI L8C50
    8C44  BD A4 0E  LDA req_units,X
    8C47  2A        ROL A
    8C48  30 F6     BMI L8C40
    8C4A  BD A5 0E  LDA req_s1,X
    8C4D  2A        ROL A
    8C4E  10 D3     BPL L8C23
.L8C50
    8C50  60        RTS
;------------------------------------------------------------------------------
; CHECKSUM FAILED: act on *OPT2 (opt2_errors)
;   0  ignore the error and accept the page
;   1  retry: wait for the page to be transmitted again (default)
;   2  give error &CA "Bad checksum on page"
; While retrying, the four sub-code digits are made wild (bit 7) so that any version of
; the page will do. "Bad data. Retrying..." is printed when Telesoftware messages are on.
;------------------------------------------------------------------------------
.L8C51
    8C51  AD 98 0E  LDA opt2_errors
    8C54  D0 03     BNE L8C59
    8C56  4C FB 8C  JMP L8CFB
.L8C59
    8C59  C9 02     CMP #&02
    8C5B  D0 19     BNE L8C76
    8C5D  20 98 A1  JSR error_inline
    8C60  .str '\xcaBad checksum on page\x00'
.L8C76
    8C76  20 A2 90  JSR clear_capture_flags ; abandon the bad copy
    8C79  BD A5 0E  LDA req_s1,X
    8C7C  09 80     ORA #&80
    8C7E  9D A5 0E  STA req_s1,X
    8C81  BD A6 0E  LDA req_s2,X
    8C84  09 80     ORA #&80
    8C86  9D A6 0E  STA req_s2,X
    8C89  BD A7 0E  LDA req_s3,X
    8C8C  09 80     ORA #&80
    8C8E  9D A7 0E  STA req_s3,X
    8C91  BD A8 0E  LDA req_s4,X
    8C94  09 80     ORA #&80
    8C96  9D A8 0E  STA req_s4,X
    8C99  AD 94 16  LDA opt1_msgs           ; Telesoftware *OPT1 'Searching' messages enabled?
    8C9C  10 21     BPL L8CBF
    8C9E  8A        TXA
    8C9F  48        PHA
    8CA0  20 AF A2  JSR print_inline
    8CA3  .str '\r\nBad data. Retrying...\r\n\x00'
    8CBD  68        PLA
    8CBE  AA        TAX
.L8CBF
    8CBF  BD A2 0E  LDA req_mag,X
    8CC2  29 BF     AND #&BF
    8CC4  9D A2 0E  STA req_mag,X
;------------------------------------------------------------------------------
; Wait for the current page, then check its checksum (if it had one) and apply *OPT2.
;------------------------------------------------------------------------------
.L8CC7
    8CC7  24 FF     BIT escape_flag
    8CC9  30 50     BMI L8D1B
    8CCB  AE 9B 0E  LDX cur_req
    8CCE  BD A5 0E  LDA req_s1,X
    8CD1  2A        ROL A
    8CD2  10 F3     BPL L8CC7
    8CD4  BD A2 0E  LDA req_mag,X
    8CD7  09 40     ORA #&40
    8CD9  9D A2 0E  STA req_mag,X
.L8CDC
    8CDC  24 FF     BIT escape_flag
    8CDE  30 3B     BMI L8D1B
    8CE0  BD A4 0E  LDA req_units,X
    8CE3  2A        ROL A
    8CE4  30 F6     BMI L8CDC
    8CE6  BD A5 0E  LDA req_s1,X
    8CE9  2A        ROL A
    8CEA  10 D3     BPL L8CBF
    8CEC  BD A6 0E  LDA req_s2,X            ; page carried a check word?
    8CEF  2A        ROL A
    8CF0  10 06     BPL L8CF8
    8CF2  BD A7 0E  LDA req_s3,X            ; and it matched?
    8CF5  2A        ROL A
    8CF6  30 03     BMI L8CFB
.L8CF8
    8CF8  4C 51 8C  JMP L8C51
;------------------------------------------------------------------------------
; Page accepted: clear the wild bits on the sub-code digits, so the request is pinned to
; the version just received.
;------------------------------------------------------------------------------
.L8CFB
    8CFB  BD A5 0E  LDA req_s1,X
    8CFE  29 7F     AND #&7F
    8D00  9D A5 0E  STA req_s1,X
    8D03  BD A6 0E  LDA req_s2,X
    8D06  29 7F     AND #&7F
    8D08  9D A6 0E  STA req_s2,X
    8D0B  BD A7 0E  LDA req_s3,X
    8D0E  29 7F     AND #&7F
    8D10  9D A7 0E  STA req_s3,X
    8D13  BD A8 0E  LDA req_s4,X
    8D16  29 7F     AND #&7F
    8D18  9D A8 0E  STA req_s4,X
.L8D1B
    8D1B  60        RTS
;------------------------------------------------------------------------------
; ptr += A * 48. Page buffers hold one 48-byte record per row.
; (A*16 is formed first; a carry out adds the 512 that A*16 overflowed by.)
;------------------------------------------------------------------------------
.row_offset
    8D1C  A0 04     LDY #&04
.L8D1E
    8D1E  0A        ASL A
    8D1F  88        DEY
    8D20  D0 FC     BNE L8D1E
    8D22  48        PHA
    8D23  90 06     BCC L8D2B
    8D25  A9 02     LDA #&02
    8D27  65 BD     ADC ptr+1
    8D29  85 BD     STA ptr+1
.L8D2B
    8D2B  A0 03     LDY #&03
.L8D2D
    8D2D  18        CLC
    8D2E  68        PLA
    8D2F  48        PHA
    8D30  65 BC     ADC ptr
    8D32  85 BC     STA ptr
    8D34  A5 BD     LDA ptr+1
    8D36  69 00     ADC #&00
    8D38  85 BD     STA ptr+1
    8D3A  88        DEY
    8D3B  D0 F0     BNE L8D2D
    8D3D  68        PLA
    8D3E  60        RTS
;------------------------------------------------------------------------------
; SERVICE CALL 5: INTERRUPT  (the heart of the system)
;
; The adapter interrupts once per field, after the vertical-blanking lines that can carry
; teletext. By then the hardware has written every teletext line it found into its 1K
; RAM: 16 slots of 64 bytes, one per line. A slot whose first byte is non-zero holds:
;   byte 1-2   magazine and row address (Hamming 8/4)
;   byte 3-42  40 data bytes; for row 0, 8 Hamming header bytes then 32 characters
; This handler does what a dedicated SAA5040 "TAC" chip would do in a normal decoder:
;   1. switch capture off so the CPU owns the RAM
;   2. for each full slot: Hamming-decode magazine and row, then
;        row 0           -> a new page header in that magazine (L8E58)
;        mag 8 row 30    -> broadcast service data (time, date, status) (8DC3)
;        other rows      -> store in the buffer of the page being captured in that magazine
;      and mark the slot empty
;   3. finish with the checksum of the current page, clear the status latch (TT_STATCLR)
;      and switch capture back on
; If DOR (data overrun) is set, a field was missed: every capture in progress is abandoned
; because rows may be missing.
;------------------------------------------------------------------------------
.svc05_irq_capture
    8D3F  2C 10 FC  BIT TT_STATUS_CTRL      ; b7 = INT: did the adapter interrupt?
    8D42  10 07     BPL L8D4B
    8D44  A9 08     LDA #&08
    8D46  2C 8E 0E  BIT ctrl_shadow         ; and are TFS interrupts enabled (b3 of the shadow)?
    8D49  D0 03     BNE L8D4E
.L8D4B
    8D4B  4C 0B 82  JMP svc_exit_unclaimed
.L8D4E
    8D4E  20 49 A2  JSR capture_off         ; capture off, IRQ off: the CPU owns the adapter RAM from here
    8D51  58        CLI                     ; allow other interrupts while we work
    8D52  A0 00     LDY #&00
.L8D54
    8D54  8C 14 0E  STY cur_slot_no
    8D57  8C 11 FC  STY TT_SLOT             ; select line slot Y
    8D5A  AD 12 FC  LDA TT_DATA             ; first byte: non-zero = the hardware wrote a line here
    8D5D  D0 28     BNE slot_has_data
.next_slot
    8D5F  AC 14 0E  LDY cur_slot_no
    8D62  C8        INY
    8D63  C0 10     CPY #&10                ; all 16 slots done?
    8D65  D0 ED     BNE L8D54
    8D67  AD 10 FC  LDA TT_STATUS_CTRL      ; read status again: b6 = DOR (data overrun)
    8D6A  85 C4     STA irq_ptr
    8D6C  24 C4     BIT irq_ptr
    8D6E  50 03     BVC L8D73
    8D70  20 8D 90  JSR abort_all_captures  ; overrun: abandon every capture in progress
.L8D73
    8D73  4C 05 91  JMP irq_finish_crc
.L8D76
    8D76  20 8D 90  JSR abort_all_captures  ; address byte uncorrectable: rows may be missing, so abandon every capture
.L8D79
    8D79  AC 14 0E  LDY cur_slot_no
    8D7C  8C 11 FC  STY TT_SLOT             ; mark the slot empty
    8D7F  A9 00     LDA #&00
    8D81  8D 12 FC  STA TT_DATA
    8D84  4C 5F 8D  JMP next_slot
;------------------------------------------------------------------------------
; A line is waiting in slot Y. Mark it empty (write 0 to byte 0), then decode the
; magazine/row address: 3 bits of magazine and 5 bits of row spread over two
; Hamming bytes.
;------------------------------------------------------------------------------
.slot_has_data
    8D87  8C 11 FC  STY TT_SLOT
    8D8A  A9 00     LDA #&00
    8D8C  8D 12 FC  STA TT_DATA             ; byte 0 := 0 (slot consumed); the counter now points at byte 1
    8D8F  AE 12 FC  LDX TT_DATA             ; first address byte
    8D92  20 C1 90  JSR hamming_decode_count; decode (and count for the tuning meter)
    8D95  30 DF     BMI L8D76
    8D97  48        PHA
    8D98  29 07     AND #&07                ; magazine 1-8 is sent as 1-7, 0 (= 8)
    8D9A  8D 0C 0E  STA cur_mag
    8D9D  A8        TAY
    8D9E  68        PLA
    8D9F  C9 08     CMP #&08                ; bit 3 is the low bit of the row number
    8DA1  08        PHP
    8DA2  AE 12 FC  LDX TT_DATA             ; second address byte
    8DA5  20 C1 90  JSR hamming_decode_count
    8DA8  10 04     BPL L8DAE
    8DAA  28        PLP
    8DAB  4C 76 8D  JMP L8D76
.L8DAE
    8DAE  28        PLP
    8DAF  2A        ROL A                   ; row = (byte2 << 1) | bit
    8DB0  8D 0B 0E  STA cur_row
    8DB3  D0 03     BNE L8DB8
    8DB5  4C 58 8E  JMP row0_page_header    ; row 0: page header
.L8DB8
    8DB8  C0 00     CPY #&00                ; magazine 8 (sent as 0) row 30?
    8DBA  D0 16     BNE L8DD2
    8DBC  AD 0B 0E  LDA cur_row
    8DBF  C9 1E     CMP #&1E
    8DC1  D0 0F     BNE L8DD2
;------------------------------------------------------------------------------
; MAGAZINE 8 ROW 30: BROADCAST SERVICE DATA PACKET -> tsdp (&0E5C), 40 bytes:
; initial page, network id, time offset, Modified Julian Date, UTC time, status message.
;------------------------------------------------------------------------------
.packet_8_30
    8DC3  A9 5C     LDA #&5C
    8DC5  85 C4     STA irq_ptr
    8DC7  A9 0E     LDA #&0E
    8DC9  85 C5     STA irq_ptr+1
    8DCB  A2 28     LDX #&28
    8DCD  A0 00     LDY #&00
    8DCF  4C 3C 8E  JMP L8E3C
;------------------------------------------------------------------------------
; Ordinary row: store it in the buffer of the page currently being captured in this
; magazine (mag_capture, &FF = none). Each buffer starts with two bytes:
;   +0  capacity in 48-byte row records
;   +1  next free record for rows 26-31 (starts at 26)
; Rows 0-25 go to the record with their own number; rows 26-31 (links, enhancements)
; are added at the next free record. Each record holds the row number at +2 and the
; 40 data bytes at +10.
;------------------------------------------------------------------------------
.L8DD2
    8DD2  BE 15 0E  LDX mag_capture,Y
    8DD5  E8        INX                     ; no capture in progress in this magazine: ignore the row
    8DD6  F0 87     BEQ next_slot
    8DD8  BD 9F 0E  LDA &0E9F,X             ; X = slot + 1, so &0E9F,X / req_buf,X are the slot's buffer address
    8DDB  85 C4     STA irq_ptr
    8DDD  BD A0 0E  LDA req_buf,X
    8DE0  85 C5     STA irq_ptr+1
    8DE2  AD 0B 0E  LDA cur_row
    8DE5  C9 1A     CMP #&1A                ; row 26 or above?
    8DE7  A0 01     LDY #&01
    8DE9  90 08     BCC L8DF3
    8DEB  B1 C4     LDA (irq_ptr),Y         ; allocate the next extra-row record
    8DED  AA        TAX
    8DEE  69 00     ADC #&00
    8DF0  91 C4     STA (irq_ptr),Y
    8DF2  8A        TXA
.L8DF3
    8DF3  88        DEY
    8DF4  D1 C4     CMP (irq_ptr),Y         ; beyond the buffer's capacity: drop the row
    8DF6  B0 4D     BCS L8E45
    8DF8  8D 08 0E  STA row_tmp             ; row_tmp = record number; multiply by 48
    8DFB  A9 00     LDA #&00
    8DFD  8D 09 0E  STA row_tmp_hi
    8E00  A0 04     LDY #&04
.L8E02
    8E02  18        CLC
    8E03  2E 08 0E  ROL row_tmp
    8E06  2E 09 0E  ROL row_tmp_hi
    8E09  88        DEY
    8E0A  D0 F6     BNE L8E02
    8E0C  18        CLC
    8E0D  A5 C4     LDA irq_ptr
    8E0F  6D 08 0E  ADC row_tmp
    8E12  85 C4     STA irq_ptr
    8E14  A5 C5     LDA irq_ptr+1
    8E16  6D 09 0E  ADC row_tmp_hi
    8E19  85 C5     STA irq_ptr+1
    8E1B  18        CLC
    8E1C  2E 08 0E  ROL row_tmp
    8E1F  2E 09 0E  ROL row_tmp_hi
    8E22  18        CLC
    8E23  A5 C4     LDA irq_ptr
    8E25  6D 08 0E  ADC row_tmp
    8E28  85 C4     STA irq_ptr
    8E2A  A5 C5     LDA irq_ptr+1
    8E2C  6D 09 0E  ADC row_tmp_hi
    8E2F  85 C5     STA irq_ptr+1
    8E31  A0 02     LDY #&02                ; record +2 = row number (marks the row as received)
    8E33  AD 0B 0E  LDA cur_row
    8E36  91 C4     STA (irq_ptr),Y
    8E38  A0 0A     LDY #&0A                ; copy 40 data bytes
    8E3A  A2 28     LDX #&28
.L8E3C
    8E3C  AD 12 FC  LDA TT_DATA             ; read the next byte from the adapter (address auto-increments)
    8E3F  91 C4     STA (irq_ptr),Y
    8E41  C8        INY
    8E42  CA        DEX
    8E43  D0 F7     BNE L8E3C
.L8E45
    8E45  4C 5F 8D  JMP next_slot
;------------------------------------------------------------------------------
; Bad Hamming code in a header: abandon the capture in this magazine.
;------------------------------------------------------------------------------
.L8E48
    8E48  AC 0C 0E  LDY cur_mag
    8E4B  BE 15 0E  LDX mag_capture,Y
    8E4E  E8        INX
    8E4F  F0 04     BEQ L8E55
    8E51  CA        DEX
    8E52  20 9D 90  JSR abort_capture
.L8E55
    8E55  4C 79 8D  JMP L8D79
;------------------------------------------------------------------------------
; ROW 0: PAGE HEADER
; Decode the 8 Hamming header bytes into hdr_bytes: page units, tens, sub-code S1-S4
; (the sub-code bytes also carry control bits C4-C6), C7-C10 and C11-C14. The control
; bits the decoder acts on are gathered into hdr_ctrl:
;   b7 C4 erase page       b6 C8 update          b3 C10 inhibit display
;   b2 C9 interrupted seq  b1 C7 suppress header b0 C11 magazine serial
; Then:
;   - copy the 32 header characters to hdr_dest (rolling headers) unless C7, C9 or C10 is
;     set; in parallel-magazine mode only headers from the requested page's magazine are shown
;   - the header ends the previous page in this magazine: if one was being captured it
;     is now complete (VALID + ARRIVED)
;   - compare the new page number with every active request; on a match start capturing
;     it (CAPTURING) into that request's buffer
;------------------------------------------------------------------------------
.row0_page_header
    8E58  A0 00     LDY #&00
.L8E5A
    8E5A  AE 12 FC  LDX TT_DATA             ; 8 header bytes
    8E5D  20 C1 90  JSR hamming_decode_count
    8E60  30 E6     BMI L8E48
    8E62  99 00 0E  STA hdr_bytes,Y
    8E65  C8        INY
    8E66  C0 08     CPY #&08
    8E68  D0 F0     BNE L8E5A
    8E6A  A9 00     LDA #&00
    8E6C  8D 13 0E  STA hdr_ctrl
    8E6F  AD 05 0E  LDA &0E05               ; sub-code thousands (2 bits)
    8E72  29 03     AND #&03
    8E74  8D 0F 0E  STA hdr_s1
    8E77  AD 04 0E  LDA &0E04               ; sub-code hundreds (4 bits)
    8E7A  29 0F     AND #&0F
    8E7C  8D 10 0E  STA hdr_s2
    8E7F  AD 03 0E  LDA &0E03               ; sub-code tens (3 bits)
    8E82  29 07     AND #&07
    8E84  8D 11 0E  STA hdr_s3
    8E87  AD 02 0E  LDA &0E02               ; sub-code units (4 bits)
    8E8A  29 0F     AND #&0F
    8E8C  8D 12 0E  STA hdr_s4
    8E8F  AD 01 0E  LDA &0E01               ; page tens
    8E92  29 0F     AND #&0F
    8E94  8D 0D 0E  STA hdr_tens
    8E97  AD 00 0E  LDA hdr_bytes           ; page units
    8E9A  29 0F     AND #&0F
    8E9C  8D 0E 0E  STA hdr_units
    8E9F  A9 04     LDA #&04                ; C9 interrupted sequence
    8EA1  2C 06 0E  BIT &0E06
    8EA4  F0 08     BEQ L8EAE
    8EA6  AD 13 0E  LDA hdr_ctrl
    8EA9  09 04     ORA #&04
    8EAB  8D 13 0E  STA hdr_ctrl
.L8EAE
    8EAE  A9 08     LDA #&08                ; C10 inhibit display
    8EB0  2C 06 0E  BIT &0E06
    8EB3  F0 08     BEQ L8EBD
    8EB5  AD 13 0E  LDA hdr_ctrl
    8EB8  09 08     ORA #&08
    8EBA  8D 13 0E  STA hdr_ctrl
.L8EBD
    8EBD  A9 01     LDA #&01                ; C11 magazine serial
    8EBF  2C 07 0E  BIT &0E07
    8EC2  F0 08     BEQ L8ECC
    8EC4  AD 13 0E  LDA hdr_ctrl
    8EC7  09 01     ORA #&01
    8EC9  8D 13 0E  STA hdr_ctrl
.L8ECC
    8ECC  A9 08     LDA #&08                ; C4 erase page
    8ECE  2C 03 0E  BIT &0E03
    8ED1  F0 08     BEQ L8EDB
    8ED3  AD 13 0E  LDA hdr_ctrl
    8ED6  09 80     ORA #&80
    8ED8  8D 13 0E  STA hdr_ctrl
.L8EDB
    8EDB  A9 02     LDA #&02                ; C8 update
    8EDD  2C 06 0E  BIT &0E06
    8EE0  F0 08     BEQ L8EEA
    8EE2  AD 13 0E  LDA hdr_ctrl
    8EE5  09 40     ORA #&40
    8EE7  8D 13 0E  STA hdr_ctrl
.L8EEA
    8EEA  A9 01     LDA #&01                ; C7 suppress header
    8EEC  2C 06 0E  BIT &0E06
    8EEF  F0 08     BEQ L8EF9
    8EF1  AD 13 0E  LDA hdr_ctrl
    8EF4  09 02     ORA #&02
    8EF6  8D 13 0E  STA hdr_ctrl
.L8EF9
    8EF9  AD 9D 0E  LDA hdr_dest+1          ; rolling headers wanted?
    8EFC  F0 4B     BEQ L8F49
    8EFE  A9 04     LDA #&04
    8F00  2C 13 0E  BIT hdr_ctrl
    8F03  D0 44     BNE L8F49
    8F05  A9 02     LDA #&02
    8F07  2C 13 0E  BIT hdr_ctrl
    8F0A  D0 3D     BNE L8F49
    8F0C  A9 08     LDA #&08
    8F0E  2C 13 0E  BIT hdr_ctrl
    8F11  D0 36     BNE L8F49
    8F13  A9 01     LDA #&01
    8F15  2C 13 0E  BIT hdr_ctrl
    8F18  D0 16     BNE L8F30               ; serial mode: every header is shown
    8F1A  AE 9B 0E  LDX cur_req             ; parallel mode: skip headers from other magazines when the current page names a magazine
    8F1D  BD A9 0E  LDA req_state,X
    8F20  C9 40     CMP #&40                ; '@'
    8F22  D0 0C     BNE L8F30
    8F24  BD A2 0E  LDA req_mag,X
    8F27  30 07     BMI L8F30
    8F29  29 07     AND #&07
    8F2B  CD 0C 0E  CMP cur_mag
    8F2E  D0 19     BNE L8F49
.L8F30
    8F30  AD 9C 0E  LDA hdr_dest            ; write the 32 header characters for display
    8F33  85 C4     STA irq_ptr
    8F35  AD 9D 0E  LDA hdr_dest+1
    8F38  85 C5     STA irq_ptr+1
    8F3A  A0 00     LDY #&00
    8F3C  A2 20     LDX #&20
.L8F3E
    8F3E  AD 12 FC  LDA TT_DATA
    8F41  09 80     ORA #&80                ; MODE 7 code
    8F43  91 C4     STA (irq_ptr),Y
    8F45  C8        INY
    8F46  CA        DEX
    8F47  D0 F5     BNE L8F3E
.L8F49
    8F49  AC 0C 0E  LDY cur_mag             ; was a page being captured in this magazine?
    8F4C  BE 15 0E  LDX mag_capture,Y
    8F4F  E8        INX
    8F50  F0 60     BEQ L8FB2
    8F52  E8        INX                     ; X = slot + 3, so req_buf,X walks req_tens..req_s4 of that slot
    8F53  E8        INX
    8F54  A0 01     LDY #&01
.L8F56
    8F56  BD A0 0E  LDA req_buf,X           ; compare the new header's page number with it (magazine already matches)
    8F59  29 0F     AND #&0F
    8F5B  D9 0C 0E  CMP cur_mag,Y
    8F5E  D0 0F     BNE L8F6F
    8F60  E8        INX
    8F61  C8        INY
    8F62  C0 07     CPY #&07
    8F64  D0 F0     BNE L8F56
    8F66  BD 9B 0E  LDA cur_req,X           ; (&0E9B+X = req_units of the slot) same page, still capturing: keep going
    8F69  2A        ROL A
    8F6A  10 03     BPL L8F6F
    8F6C  4C 5F 8D  JMP next_slot
.L8F6F
    8F6F  AC 0C 0E  LDY cur_mag             ; different page: the old capture is finished
    8F72  BE 15 0E  LDX mag_capture,Y
    8F75  A9 FF     LDA #&FF
    8F77  99 15 0E  STA mag_capture,Y
    8F7A  E8        INX
    8F7B  F0 35     BEQ L8FB2
    8F7D  CA        DEX
    8F7E  BD A9 0E  LDA req_state,X
    8F81  2A        ROL A
    8F82  10 2E     BPL L8FB2
    8F84  BD A4 0E  LDA req_units,X         ; was it CAPTURING?
    8F87  2A        ROL A
    8F88  10 28     BPL L8FB2
    8F8A  BD A4 0E  LDA req_units,X         ; CAPTURING off, VALID on, ARRIVED on; checksum flags cleared
    8F8D  29 BF     AND #&BF
    8F8F  9D A4 0E  STA req_units,X
    8F92  BD A5 0E  LDA req_s1,X
    8F95  09 40     ORA #&40
    8F97  9D A5 0E  STA req_s1,X
    8F9A  BD A3 0E  LDA req_tens,X
    8F9D  09 40     ORA #&40
    8F9F  9D A3 0E  STA req_tens,X
    8FA2  BD A7 0E  LDA req_s3,X
    8FA5  29 BF     AND #&BF
    8FA7  9D A7 0E  STA req_s3,X
    8FAA  BD A6 0E  LDA req_s2,X
    8FAD  29 BF     AND #&BF
    8FAF  9D A6 0E  STA req_s2,X
;------------------------------------------------------------------------------
; Look for a request (slots 0-24, 10 bytes apart) that wants this page.
;------------------------------------------------------------------------------
.L8FB2
    8FB2  A2 F6     LDX #&F6
    8FB4  8E 0A 0E  STX slot_scan
.L8FB7
    8FB7  AD 0A 0E  LDA slot_scan
    8FBA  C9 F0     CMP #&F0
    8FBC  D0 03     BNE L8FC1
    8FBE  4C 5F 8D  JMP next_slot
.L8FC1
    8FC1  18        CLC
    8FC2  69 0A     ADC #&0A
    8FC4  AA        TAX
    8FC5  8D 0A 0E  STA slot_scan
    8FC8  BD A9 0E  LDA req_state,X         ; must be an active slot (&40)
    8FCB  C9 40     CMP #&40                ; '@'
    8FCD  D0 E8     BNE L8FB7
    8FCF  BD A4 0E  LDA req_units,X         ; marked CAPTURING? Only skip it if that capture is really still running
    8FD2  2A        ROL A
    8FD3  10 13     BPL L8FE8
    8FD5  BD A2 0E  LDA req_mag,X
    8FD8  29 07     AND #&07
    8FDA  A8        TAY
    8FDB  B9 15 0E  LDA mag_capture,Y
    8FDE  C9 FF     CMP #&FF
    8FE0  D0 D5     BNE L8FB7
    8FE2  20 A2 90  JSR clear_capture_flags
    8FE5  4C B7 8F  JMP L8FB7
.L8FE8
    8FE8  BD A2 0E  LDA req_mag,X           ; locked slots are not overwritten
    8FEB  2A        ROL A
    8FEC  30 C9     BMI L8FB7
    8FEE  BD A5 0E  LDA req_s1,X            ; already hold a valid copy? Then only re-capture if C8 (update) is set, or the copy
    8FF1  2A        ROL A
    8FF2  10 13     BPL L9007
    8FF4  2C 13 0E  BIT hdr_ctrl
    8FF7  70 0E     BVS L9007
    8FF9  BD A7 0E  LDA req_s3,X            ; failed its checksum (CHECK WORD present but CHECKSUM OK clear)
