    9F55  A0 00     LDY #&00
    9F57  B1 B4     LDA (fblk),Y            ; zp_b0/zp_b1 = address of the file name
    9F59  85 B0     STA zp_b0
    9F5B  C8        INY
    9F5C  B1 B4     LDA (fblk),Y
    9F5E  85 B1     STA zp_b1
