    9F77  C8        INY
    9F78  D0 F5     BNE L9F6F
.L9F7A
    9F7A  A9 0D     LDA #&0D
    9F7C  91 B6     STA (count),Y
    9F7E  A9 07     LDA #&07
    9F80  A6 B4     LDX fblk
    9F82  A4 B5     LDY fblk+1
    9F84  20 94 AC  JSR LAC94               ; start reading the named file (OSFILE 7 is used internally for this)
    9F87  AD 9A 19  LDA run_flag
    9F8A  F0 19     BEQ L9FA5
    9F8C  A0 06     LDY #&06
    9F8E  B1 B4     LDA (fblk),Y
    9F90  F0 13     BEQ L9FA5
    9F92  20 98 A1  JSR error_inline
    9F95  .str '\xfeCannot execute\x00'
.L9FA5
    9FA5  A9 00     LDA #&00
