    9FA9  85 B7     STA count+1
.L9FAB
    9FAB  A0 0E     LDY #&0E                ; BGET channel 14: next decoded byte of the file
    9FAD  20 A9 83  JSR bgetv
    9FB0  90 20     BCC L9FD2
    9FB2  C9 FE     CMP #&FE                ; &FE: end of file (or ESCAPE)
    9FB4  F0 36     BEQ L9FEC
    9FB6  C9 02     CMP #&02                ; 2: a new block started: re-read the file information
    9FB8  D0 15     BNE L9FCF
    9FBA  A9 05     LDA #&05
    9FBC  A6 B4     LDX fblk
    9FBE  A4 B5     LDY fblk+1
    9FC0  20 1A AD  JSR LAD1A
    9FC3  A0 02     LDY #&02                ; and take its load address
.L9FC5
    9FC5  B1 B4     LDA (fblk),Y
    9FC7  99 AE 00  STA &00AE,Y
    9FCA  C8        INY
    9FCB  C0 06     CPY #&06
    9FCD  D0 F6     BNE L9FC5
.L9FCF
    9FCF  18        CLC
    9FD0  90 D9     BCC L9FAB
.L9FD2
    9FD2  85 BA     STA xfer_byte           ; store the byte at the load address (Tube aware)
    9FD4  A9 01     LDA #&01
    9FD6  A2 B0     LDX #&B0
    9FD8  A0 00     LDY #&00
    9FDA  20 CE A2  JSR LA2CE
    9FDD  E6 B0     INC zp_b0
    9FDF  D0 02     BNE L9FE3
    9FE1  E6 B1     INC zp_b1
.L9FE3
    9FE3  E6 B6     INC count               ; count the bytes loaded
    9FE5  D0 02     BNE L9FE9
    9FE7  E6 B7     INC count+1
.L9FE9
    9FE9  18        CLC
    9FEA  90 BF     BCC L9FAB
;------------------------------------------------------------------------------
; End of file: store the length (count) into the parameter block, and the attributes.
;------------------------------------------------------------------------------
.L9FEC
    9FEC  A0 0A     LDY #&0A
    9FEE  B1 B4     LDA (fblk),Y
    9FF0  48        PHA
    9FF1  A5 B6     LDA count
    9FF3  91 B4     STA (fblk),Y
    9FF5  A5 B7     LDA count+1
    9FF7  C8        INY
    9FF8  91 B4     STA (fblk),Y
    9FFA  A9 00     LDA #&00
    9FFC  C8        INY
    9FFD  91 B4     STA (fblk),Y
    9FFF  C8        INY
    A000  91 B4     STA (fblk),Y            ; (TFS103.ROM has a corrupt byte here: &00 instead of &91)
    A002  68        PLA
    A003  C8        INY
    A004  91 B4     STA (fblk),Y
    A006  60        RTS
;------------------------------------------------------------------------------
; FSC 2 and 4: */ and *RUN. Load the file with run_flag set, then jump to its execution
; address, through the Tube if a second processor is present.
;------------------------------------------------------------------------------
.LA007
    A007  A9 01     LDA #&01
    A009  8D 9A 19  STA run_flag
    A00C  20 51 9F  JSR L9F51
    A00F  A0 06     LDY #&06
.LA011
    A011  B1 B4     LDA (fblk),Y            ; copy the execution address to &199A..&199D (overwriting run_flag)
    A013  99 94 19  STA &1994,Y
    A016  C8        INY
    A017  C0 0A     CPY #&0A
    A019  D0 F6     BNE LA011
    A01B  20 3F A3  JSR LA33F               ; Tube present?
    A01E  F0 03     BEQ LA023
    A020  6C 9A 19  JMP (run_flag)          ; no: just jump to it
.LA023
    A023  20 31 A3  JSR LA331
    A026  08        PHP
    A027  78        SEI
    A028  A9 04     LDA #&04                ; Tube: claim it and tell the second processor to start at the address in &199A
    A02A  A2 9A     LDX #&9A
    A02C  A0 19     LDY #&19
    A02E  20 06 04  JSR TUBE_CODE
    A031  20 39 A3  JSR LA339
    A034  28        PLP
    A035  60        RTS
;------------------------------------------------------------------------------
; Error &CF "Data not available" (also used for OSGBPB and reserved OSWORD calls).
;------------------------------------------------------------------------------
.error_not_available
    A036  20 98 A1  JSR error_inline
    A039  .str '\xcfData not available\x00'
;------------------------------------------------------------------------------
; *ITV1 / *ITV2: channel 3 / 4. The digit after the command is in (ptr),Y.
;------------------------------------------------------------------------------
.cmd_ITV
    A04D  B1 BC     LDA (ptr),Y
    A04F  18        CLC
    A050  69 02     ADC #&02
    A052  4C 57 A0  JMP LA057
;------------------------------------------------------------------------------
; *BBC1 / *BBC2 / *CH1-*CH4: channel = digit - 1.
; Three dummy bytes are pushed as a service-call frame so that the SELECT CHANNEL code,
; which ends with JMP svc_exit_claimed, returns here cleanly.
;------------------------------------------------------------------------------
.cmd_BBC_CH
    A055  B1 BC     LDA (ptr),Y
.LA057
    A057  38        SEC
    A058  E9 31     SBC #&31
    A05A  48        PHA
    A05B  48        PHA
    A05C  48        PHA
    A05D  38        SEC
    A05E  4C 95 8A  JMP L8A95
; Fill osw_blk+1..+7 with &FF (all seven page digits wild).
.LA061
    A061  A2 07     LDX #&07
    A063  A9 FF     LDA #&FF
.LA065
    A065  9D 3A 0E  STA osw_blk,X
    A068  CA        DEX
    A069  D0 FA     BNE LA065
    A06B  60        RTS
;------------------------------------------------------------------------------
; *PAGE <digits>: up to 7 characters 0-9, A-F or "#" (wild). Digits not given stay wild,
; so *PAGE 100 means page 100 with any sub-code. Issues OSWORD &7A &85 FETCH PAGE.
;------------------------------------------------------------------------------
.cmd_PAGE
    A06C  20 61 A0  JSR LA061
    A06F  B1 BC     LDA (ptr),Y
    A071  C9 2E     CMP #&2E                ; '.'
    A073  D0 01     BNE LA076
    A075  C8        INY
.LA076
    A076  B1 BC     LDA (ptr),Y
    A078  C8        INY
    A079  C9 0D     CMP #&0D
    A07B  F0 3D     BEQ LA0BA
    A07D  C9 20     CMP #&20
    A07F  F0 F5     BEQ LA076
    A081  C9 23     CMP #&23                ; '#'
    A083  F0 1B     BEQ LA0A0
    A085  C9 30     CMP #&30                ; '0'
    A087  90 1F     BCC LA0A8
    A089  C9 3A     CMP #&3A                ; ':'
    A08B  90 13     BCC LA0A0
    A08D  C9 41     CMP #&41                ; 'A'
    A08F  90 17     BCC LA0A8
    A091  C9 47     CMP #&47                ; 'G'
    A093  90 0B     BCC LA0A0
    A095  C9 61     CMP #&61                ; 'a'
    A097  90 0F     BCC LA0A8
    A099  C9 67     CMP #&67                ; 'g'
    A09B  90 03     BCC LA0A0
    A09D  4C A8 A0  JMP LA0A8
.LA0A0
    A0A0  E8        INX
    A0A1  9D 3A 0E  STA osw_blk,X
    A0A4  E0 08     CPX #&08
    A0A6  D0 CE     BNE LA076
.LA0A8
    A0A8  20 98 A1  JSR error_inline        ; anything else: "Bad parameter"
    A0AB  .str '\xccBad parameter\x00'
.LA0BA
    A0BA  A9 85     LDA #&85                ; FETCH PAGE
    A0BC  8D 3A 0E  STA osw_blk
; Issue OSWORD &7A with the block at osw_blk.
.LA0BF
    A0BF  A9 7A     LDA #&7A
    A0C1  A2 3A     LDX #&3A
    A0C3  A0 0E     LDY #&0E
    A0C5  20 F1 FF  JSR OSWORD
    A0C8  38        SEC
    A0C9  60        RTS
;------------------------------------------------------------------------------
; Parse a hexadecimal address (3 to 8 digits) into osw_blk+1..+4, low byte first.
;------------------------------------------------------------------------------
.LA0CA
    A0CA  A2 04     LDX #&04
    A0CC  A9 00     LDA #&00
.LA0CE
    A0CE  9D 3A 0E  STA osw_blk,X
    A0D1  CA        DEX
    A0D2  D0 FA     BNE LA0CE
    A0D4  B1 BC     LDA (ptr),Y
    A0D6  C9 2E     CMP #&2E                ; '.'
    A0D8  F0 04     BEQ LA0DE
    A0DA  C9 20     CMP #&20
    A0DC  D0 CA     BNE LA0A8
.LA0DE
    A0DE  C8        INY
    A0DF  B1 BC     LDA (ptr),Y
    A0E1  C9 20     CMP #&20
    A0E3  F0 F9     BEQ LA0DE
    A0E5  A2 00     LDX #&00
.LA0E7
    A0E7  B1 BC     LDA (ptr),Y
    A0E9  C9 0D     CMP #&0D
    A0EB  F0 08     BEQ LA0F5
    A0ED  C9 20     CMP #&20
    A0EF  F0 B7     BEQ LA0A8
    A0F1  E8        INX
    A0F2  C8        INY
    A0F3  D0 F2     BNE LA0E7
.LA0F5
    A0F5  E0 03     CPX #&03
    A0F7  90 AF     BCC LA0A8
    A0F9  88        DEY
    A0FA  A2 00     LDX #&00
.LA0FC
    A0FC  E8        INX
    A0FD  E0 06     CPX #&06
    A0FF  F0 A7     BEQ LA0A8
    A101  20 1F A1  JSR LA11F
    A104  B0 15     BCS LA11B
    A106  9D 3A 0E  STA osw_blk,X
    A109  20 1F A1  JSR LA11F
    A10C  B0 0D     BCS LA11B
    A10E  0A        ASL A
    A10F  0A        ASL A
    A110  0A        ASL A
    A111  0A        ASL A
    A112  1D 3A 0E  ORA osw_blk,X
    A115  9D 3A 0E  STA osw_blk,X
    A118  4C FC A0  JMP LA0FC
.LA11B
    A11B  60        RTS
.LA11C
    A11C  4C A8 A0  JMP LA0A8
;------------------------------------------------------------------------------
; Read one hex digit (working backwards from the end of the address). C set at the start
; of the address (space or ".").
;------------------------------------------------------------------------------
.LA11F
    A11F  B1 BC     LDA (ptr),Y
    A121  C9 2E     CMP #&2E                ; '.'
    A123  F0 04     BEQ LA129
    A125  C9 20     CMP #&20
    A127  D0 02     BNE LA12B
.LA129
    A129  38        SEC
    A12A  60        RTS
.LA12B
    A12B  88        DEY
    A12C  38        SEC
    A12D  E9 30     SBC #&30
    A12F  30 EB     BMI LA11C
    A131  C9 0A     CMP #&0A
    A133  90 0A     BCC LA13F
    A135  E9 11     SBC #&11
    A137  30 E3     BMI LA11C
    A139  C9 06     CMP #&06
    A13B  B0 04     BCS LA141
.LA13D
    A13D  69 0A     ADC #&0A
.LA13F
    A13F  18        CLC
    A140  60        RTS
.LA141
    A141  E9 20     SBC #&20
    A143  30 D7     BMI LA11C
    A145  C9 06     CMP #&06
    A147  B0 D3     BCS LA11C
    A149  90 F2     BCC LA13D
; FSC 5 (*CAT): not supported: "Bad command".
.LA14B
    A14B  4C FA A1  JMP LA1FA
;------------------------------------------------------------------------------
; *TRANSFER <addr>: OSWORD &7A &8F TRANSFER the current page to <addr>.
;------------------------------------------------------------------------------
.cmd_TRANSFER
    A14E  20 61 A0  JSR LA061
    A151  20 CA A0  JSR LA0CA
    A154  A9 8F     LDA #&8F
    A156  8D 3A 0E  STA osw_blk
    A159  4C BF A0  JMP LA0BF
;------------------------------------------------------------------------------
; *DISPLAY <addr>: MODE 7, then print the 960 bytes stored at <addr> by *TRANSFER
; (bit 7 set, zero shown as a space) until the cursor reaches the bottom row.
;------------------------------------------------------------------------------
.cmd_DISPLAY
    A15C  20 CA A0  JSR LA0CA
    A15F  20 AF A2  JSR print_inline
    A162  .str '\x16\x07\x00'
.LA165
    A165  A2 3B     LDX #&3B
    A167  A0 0E     LDY #&0E
    A169  A9 00     LDA #&00
    A16B  20 CE A2  JSR LA2CE               ; read a byte (Tube aware)
    A16E  C9 00     CMP #&00
    A170  D0 02     BNE LA174
    A172  A9 20     LDA #&20
.LA174
    A174  09 80     ORA #&80
    A176  20 EE FF  JSR OSWRCH
    A179  A9 86     LDA #&86                ; stop at row 24
    A17B  20 F4 FF  JSR OSBYTE              ; OSBYTE &86: read text cursor position
    A17E  C0 18     CPY #&18
    A180  F0 15     BEQ LA197
    A182  EE 3B 0E  INC osw_blk+1
    A185  D0 DE     BNE LA165
    A187  EE 3C 0E  INC osw_blk+2
    A18A  D0 D9     BNE LA165
    A18C  EE 3D 0E  INC osw_blk+3
    A18F  D0 D4     BNE LA165
    A191  EE 3E 0E  INC &0E3E
    A194  4C 65 A1  JMP LA165
.LA197
    A197  60        RTS
;------------------------------------------------------------------------------
; RAISE AN ERROR: the bytes after the JSR are the error number and message,
; zero-terminated. They are copied to &0100 behind a BRK (&00) which is then executed.
;------------------------------------------------------------------------------
.error_inline
    A198  68        PLA
    A199  85 BC     STA ptr
    A19B  68        PLA
    A19C  85 BD     STA ptr+1
    A19E  A9 00     LDA #&00
    A1A0  A8        TAY
    A1A1  8D 00 01  STA stack_page
.LA1A4
    A1A4  C8        INY
    A1A5  B1 BC     LDA (ptr),Y
    A1A7  99 00 01  STA stack_page,Y
    A1AA  D0 F8     BNE LA1A4
    A1AC  4C 00 01  JMP stack_page
;------------------------------------------------------------------------------
; FSCV: FILING SYSTEM CONTROL, A = reason code (table at &A266):
;   0 *OPT          1 EOF            2 */           3 unrecognised * command
;   4 *RUN          5 *CAT (Bad command)  6 another filing system starting: stop capture
;   7 report the range of file handles (&0E-&0F)
;------------------------------------------------------------------------------
.fscv
    A1AF  85 BC     STA ptr
    A1B1  48        PHA
    A1B2  8A        TXA
    A1B3  48        PHA
    A1B4  A5 BC     LDA ptr
    A1B6  C9 08     CMP #&08
    A1B8  90 04     BCC LA1BE
    A1BA  68        PLA
    A1BB  AA        TAX
    A1BC  68        PLA
    A1BD  60        RTS
.LA1BE
    A1BE  0A        ASL A
    A1BF  AA        TAX
    A1C0  BD 66 A2  LDA fsc_table,X
    A1C3  85 BC     STA ptr
    A1C5  BD 67 A2  LDA &A267,X
    A1C8  85 BD     STA ptr+1
    A1CA  68        PLA
    A1CB  AA        TAX
    A1CC  68        PLA
    A1CD  6C BC 00  JMP (ptr)
;------------------------------------------------------------------------------
; FSC 7: TFS uses handles &0E (decoded Telesoftware file) and &0F (raw page).
;------------------------------------------------------------------------------
.LA1D0
    A1D0  A2 0E     LDX #&0E
    A1D2  A0 0F     LDY #&0F
    A1D4  60        RTS
;------------------------------------------------------------------------------
; FSC 1: EOF#X. Returns the end-of-file flag for handle &0E or &0F.
;------------------------------------------------------------------------------
.LA1D5
    A1D5  E0 0E     CPX #&0E
    A1D7  D0 04     BNE LA1DD
    A1D9  AE 9E 0E  LDX &0E9E
    A1DC  60        RTS
.LA1DD
    A1DD  E0 0F     CPX #&0F
    A1DF  D0 04     BNE LA1E5
    A1E1  AE 9F 0E  LDX &0E9F
    A1E4  60        RTS
.LA1E5
    A1E5  4C B7 83  JMP L83B7
;------------------------------------------------------------------------------
; FSC 3: an unrecognised * command while TFS is the filing system: look it up in the
; * command table, otherwise "Bad command".
;------------------------------------------------------------------------------
.LA1E8
    A1E8  48        PHA
    A1E9  8A        TXA
    A1EA  48        PHA
    A1EB  85 BC     STA ptr
    A1ED  98        TYA
    A1EE  48        PHA
    A1EF  85 BD     STA ptr+1
    A1F1  A2 00     LDX #&00
    A1F3  A0 00     LDY #&00
    A1F5  20 87 9E  JSR match_star_command
    A1F8  B0 10     BCS LA20A
.LA1FA
    A1FA  20 98 A1  JSR error_inline
    A1FD  .str '\xfeBad command\x00'
.LA20A
    A20A  4C 11 82  JMP svc_exit_claimed
;------------------------------------------------------------------------------
; FSC 0: *OPT X,Y
;   *OPT 0     defaults (*OPT1,128 *OPT2,1 *OPT3,0)
;   *OPT 1,n   Telesoftware messages (bit 7: "Searching..." etc.)
;   *OPT 2,n   checksum errors: 0 ignore, 1 retry, 2 error
;   *OPT 3,n   1 = keep name-table changes from one file to the next
;------------------------------------------------------------------------------
.LA20D
    A20D  E0 00     CPX #&00
    A20F  D0 0F     BNE LA220
    A211  A9 01     LDA #&01
    A213  8D 98 0E  STA opt2_errors
    A216  A9 80     LDA #&80
    A218  20 7C AC  JSR LAC7C
    A21B  A9 00     LDA #&00
    A21D  4C 80 AC  JMP LAC80
.LA220
    A220  E0 01     CPX #&01
    A222  D0 05     BNE LA229
    A224  98        TYA
    A225  20 7C AC  JSR LAC7C
    A228  60        RTS
.LA229
    A229  E0 02     CPX #&02
    A22B  D0 05     BNE LA232
    A22D  98        TYA
    A22E  8D 98 0E  STA opt2_errors
    A231  60        RTS
.LA232
    A232  E0 03     CPX #&03
    A234  D0 04     BNE LA23A
    A236  98        TYA
    A237  4C 80 AC  JMP LAC80
.LA23A
    A23A  20 98 A1  JSR error_inline
    A23D  .str '\xcbBad option\x00'
;------------------------------------------------------------------------------
; Stop the adapter: clear b3 (IRQ enable) in the latch and the shadow, then also clear b2
; (TTXEN, capture enable) in the latch only. The CPU then owns the adapter RAM. The shadow
; keeps b2 set so that capture_on restores it.
;------------------------------------------------------------------------------
.capture_off
    A249  AD 8E 0E  LDA ctrl_shadow
    A24C  29 F7     AND #&F7
    A24E  8D 10 FC  STA TT_STATUS_CTRL
    A251  8D 8E 0E  STA ctrl_shadow
    A254  29 FB     AND #&FB
    A256  8D 10 FC  STA TT_STATUS_CTRL
    A259  60        RTS
;------------------------------------------------------------------------------
; Restart the adapter: b3 (IRQ enable) back on; b2 (capture) comes back from the shadow.
;------------------------------------------------------------------------------
.capture_on
    A25A  AD 8E 0E  LDA ctrl_shadow
    A25D  09 08     ORA #&08
    A25F  8D 8E 0E  STA ctrl_shadow
    A262  8D 10 FC  STA TT_STATUS_CTRL
    A265  60        RTS
; FSC reason code dispatch table (codes 0-7).
.fsc_table
    A266  .db 0D A2 D5 A1 07 A0 E8 A1 07 A0 4B A1 49 A2 D0 A1  ; ..........K.I...
; Copy the 4-byte address at (ptr) to ptr2..&C3.
.LA276
    A276  A0 00     LDY #&00
    A278  B1 BC     LDA (ptr),Y
    A27A  85 C0     STA ptr2
    A27C  C8        INY
    A27D  B1 BC     LDA (ptr),Y
    A27F  85 C1     STA ptr2+1
    A281  C8        INY
    A282  B1 BC     LDA (ptr),Y
    A284  85 C2     STA &C2
    A286  C8        INY
    A287  B1 BC     LDA (ptr),Y
    A289  85 C3     STA &C3
    A28B  60        RTS
;------------------------------------------------------------------------------
; Store A at the 32-bit address ptr2..&C3 and step the address (Tube aware).
;------------------------------------------------------------------------------
.LA28C
    A28C  8D 1D 0E  STA &0E1D
    A28F  98        TYA
    A290  48        PHA
    A291  8A        TXA
    A292  48        PHA
    A293  A2 C0     LDX #&C0
    A295  A0 00     LDY #&00
    A297  AD 1D 0E  LDA &0E1D
    A29A  85 BA     STA xfer_byte
    A29C  A9 01     LDA #&01
    A29E  20 CE A2  JSR LA2CE
    A2A1  E6 C0     INC ptr2
    A2A3  D0 02     BNE LA2A7
    A2A5  E6 C1     INC ptr2+1
.LA2A7
    A2A7  68        PLA
    A2A8  AA        TAX
    A2A9  68        PLA
    A2AA  A8        TAY
    A2AB  AD 1D 0E  LDA &0E1D
    A2AE  60        RTS
;------------------------------------------------------------------------------
; PRINT INLINE STRING: prints the zero-terminated bytes that follow the JSR and returns
; to the instruction after the terminator.
;------------------------------------------------------------------------------
.print_inline
    A2AF  68        PLA
    A2B0  85 BC     STA ptr
    A2B2  68        PLA
    A2B3  85 BD     STA ptr+1
    A2B5  A0 01     LDY #&01
    A2B7  08        PHP
    A2B8  88        DEY
.LA2B9
    A2B9  E6 BC     INC ptr
    A2BB  D0 02     BNE LA2BF
    A2BD  E6 BD     INC ptr+1
.LA2BF
    A2BF  28        PLP
    A2C0  F0 09     BEQ LA2CB
    A2C2  B1 BC     LDA (ptr),Y
    A2C4  08        PHP
    A2C5  20 EE FF  JSR OSWRCH
    A2C8  4C B9 A2  JMP LA2B9
.LA2CB
    A2CB  6C BC 00  JMP (ptr)
;------------------------------------------------------------------------------
; READ OR WRITE ONE BYTE ANYWHERE: X/Y point to a 4-byte address in zero page,
; A=0 read (result in A), A=1 write xfer_byte. Addresses &FFFFxxxx, or any address when
; there is no Tube, are in this machine. Others are reached through the Tube: claim it,
; set up a single-byte transfer, move the byte through Tube register 3, release it.
;------------------------------------------------------------------------------
.LA2CE
    A2CE  48        PHA
    A2CF  86 B8     STX xfer_blk
    A2D1  84 B9     STY xfer_blk+1
    A2D3  A0 03     LDY #&03                ; top two bytes &FFFF: I/O processor memory
    A2D5  B1 B8     LDA (xfer_blk),Y
    A2D7  C9 FF     CMP #&FF
    A2D9  D0 1E     BNE LA2F9
    A2DB  88        DEY
    A2DC  B1 B8     LDA (xfer_blk),Y
    A2DE  C9 FF     CMP #&FF
    A2E0  D0 17     BNE LA2F9
.LA2E2
    A2E2  88        DEY
    A2E3  B1 B8     LDA (xfer_blk),Y
    A2E5  48        PHA
    A2E6  88        DEY
    A2E7  B1 B8     LDA (xfer_blk),Y
    A2E9  85 B8     STA xfer_blk
    A2EB  68        PLA
    A2EC  85 B9     STA xfer_blk+1
    A2EE  68        PLA
    A2EF  F0 05     BEQ LA2F6
    A2F1  A5 BA     LDA xfer_byte
    A2F3  91 B8     STA (xfer_blk),Y
    A2F5  60        RTS
.LA2F6
    A2F6  B1 B8     LDA (xfer_blk),Y
    A2F8  60        RTS
.LA2F9
    A2F9  20 3F A3  JSR LA33F               ; no Tube: also local
    A2FC  08        PHP
    A2FD  A0 02     LDY #&02
    A2FF  28        PLP
    A300  F0 E0     BEQ LA2E2
    A302  20 31 A3  JSR LA331               ; claim the Tube
    A305  68        PLA
    A306  08        PHP
    A307  48        PHA
    A308  78        SEI
