;------------------------------------------------------------------------------
; DECODE ONE NAME FROM THE PAGE
; Remember the read position (OSWORD &84), fetch the next raw byte, and look it up:
;   kind 0      ignore
;   kind 1      emit one byte (nm_lo)
;   kind 2      emit two bytes
;   kind 3+     emit the string at (nm_lo, nm_hi)
;   kind &1B    escape operator: look the next name up in the escaped tables
;   kind &1F    <UER> transmission error: reload the page and restart the block
;   kind &1x    a command: run it if its pass number matches the current pass
;   kind >&1F   error &CA
; Data is only emitted inside a block (ts_state 2) or while a command reads an operand.
;------------------------------------------------------------------------------
.ts_decode_name
    AA6E  20 15 A9  JSR push_frame
    AA71  A9 84     LDA #&84                ; OSWORD &84: mark the position of this name
    AA73  20 D3 A9  JSR ts_osword
.LAA76
    AA76  20 DF A8  JSR use_lone_tables
.LAA79
    AA79  20 7F AB  JSR ts_rawbyte          ; next raw byte from the page
    AA7C  90 05     BCC LAA83
    AA7E  20 56 A9  JSR pop_frame
    AA81  38        SEC
    AA82  60        RTS
.LAA83
    AA83  A8        TAY
    AA84  B1 C6     LDA (nm_kind),Y         ; kind of this name
    AA86  AA        TAX
    AA87  F0 62     BEQ LAAEB
    AA89  C9 1B     CMP #&1B                ; escape operator?
    AA8B  F0 58     BEQ LAAE5
    AA8D  C9 1F     CMP #&1F                ; <UER>?
    AA8F  F0 44     BEQ LAAD5
    AA91  B0 3D     BCS LAAD0
    AA93  29 10     AND #&10                ; a command?
    AA95  D0 59     BNE LAAF0
    AA97  A9 02     LDA #&02
    AA99  CD 20 16  CMP ts_state
    AA9C  F0 05     BEQ LAAA3
    AA9E  AD 4B 16  LDA ts_operand
    AAA1  F0 48     BEQ LAAEB
.LAAA3
    AAA3  E0 02     CPX #&02
    AAA5  30 21     BMI LAAC8
    AAA7  F0 1A     BEQ LAAC3
    AAA9  B1 C8     LDA (nm_lo),Y
    AAAB  85 CC     STA ts_ptr
    AAAD  B1 CA     LDA (nm_hi),Y
    AAAF  85 CD     STA ts_ptr+1
    AAB1  A0 00     LDY #&00
    AAB3  B1 CC     LDA (ts_ptr),Y
    AAB5  F0 34     BEQ LAAEB
    AAB7  AA        TAX
.LAAB8
    AAB8  C8        INY
    AAB9  B1 CC     LDA (ts_ptr),Y
    AABB  20 4D AB  JSR ts_emit
    AABE  CA        DEX
    AABF  D0 F7     BNE LAAB8
    AAC1  F0 28     BEQ LAAEB
.LAAC3
    AAC3  B1 CA     LDA (nm_hi),Y
    AAC5  20 4D AB  JSR ts_emit
.LAAC8
    AAC8  B1 C8     LDA (nm_lo),Y
    AACA  20 4D AB  JSR ts_emit
    AACD  4C EB AA  JMP LAAEB
.LAAD0
    AAD0  A9 CA     LDA #&CA
    AAD2  4C 0D AA  JMP ts_error
.LAAD5
    AAD5  20 BE AB  JSR ts_reset_queue      ; <UER>: OSWORD &80 RELOAD PAGE and start the block again
    AAD8  A9 00     LDA #&00
    AADA  8D 20 16  STA ts_state
    AADD  A9 80     LDA #&80
    AADF  20 D3 A9  JSR ts_osword
    AAE2  4C 76 AA  JMP LAA76
.LAAE5
    AAE5  20 FA A8  JSR use_escaped_tables
    AAE8  4C 79 AA  JMP LAA79
.LAAEB
    AAEB  20 56 A9  JSR pop_frame
    AAEE  18        CLC
    AAEF  60        RTS
.LAAF0
