    AAF1  29 0F     AND #&0F
    AAF3  CD 20 16  CMP ts_state
    AAF6  D0 F3     BNE LAAEB
    AAF8  B1 C8     LDA (nm_lo),Y
    AAFA  85 CC     STA ts_ptr
    AAFC  B1 CA     LDA (nm_hi),Y
    AAFE  85 CD     STA ts_ptr+1
    AB00  20 0D AB  JSR LAB0D
    AB03  B0 03     BCS LAB08
    AB05  4C EB AA  JMP LAAEB
.LAB08
