    AB4C  60        RTS
;------------------------------------------------------------------------------
; Put a decoded byte on the output queue (which grows down from &1999 towards the heap).
; Error &CD if it meets the heap.
;------------------------------------------------------------------------------
.ts_emit
    AB4D  48        PHA
    AB4E  20 15 A9  JSR push_frame
    AB51  68        PLA
    AB52  AC 1C 16  LDY outq_wr
    AB55  84 CC     STY ts_ptr
    AB57  CE 1C 16  DEC outq_wr
    AB5A  AE 1D 16  LDX outq_wr+1
    AB5D  86 CD     STX ts_ptr+1
    AB5F  C0 00     CPY #&00
    AB61  D0 03     BNE LAB66
    AB63  CE 1D 16  DEC outq_wr+1
.LAB66
    AB66  EC 93 16  CPX heap+1
    AB69  90 07     BCC LAB72
    AB6B  D0 0A     BNE LAB77
    AB6D  CC 92 16  CPY heap
    AB70  B0 05     BCS LAB77
.LAB72
    AB72  A9 CD     LDA #&CD
    AB74  4C 0D AA  JMP ts_error
.LAB77
    AB77  A0 00     LDY #&00
    AB79  91 CC     STA (ts_ptr),Y
    AB7B  20 56 A9  JSR pop_frame
    AB7E  60        RTS
;------------------------------------------------------------------------------
; NEXT RAW BYTE FROM THE PAGE: BGET channel 15. At the end of the page, unlock it and ask
; for the next page of the file: HEAD OF CHAIN (&88) when blocks may come in any order,
; otherwise CHAINED PAGE (&86). ESCAPE or a page error gives error &CE.
;------------------------------------------------------------------------------
.ts_rawbyte
    AB7F  8C 66 16  STY ts_savey
.LAB82
    AB82  A0 0F     LDY #&0F
    AB84  20 D7 FF  JSR OSBGET
    AB87  90 29     BCC LABB2
    AB89  C9 FE     CMP #&FE
    AB8B  F0 20     BEQ LABAD
    AB8D  C9 01     CMP #&01
    AB8F  30 1C     BMI LABAD
    AB91  D0 03     BNE LAB96
    AB93  EE 24 16  INC ts_eof              ; count the page
.LAB96
    AB96  A9 9A     LDA #&9A                ; OSWORD &9A: release this page
    AB98  20 D3 A9  JSR ts_osword
    AB9B  AD 68 16  LDA ts_random
    AB9E  F0 05     BEQ LABA5
    ABA0  A9 88     LDA #&88
    ABA2  4C A7 AB  JMP LABA7
.LABA5
    ABA5  A9 86     LDA #&86
.LABA7
    ABA7  20 D3 A9  JSR ts_osword
    ABAA  4C 82 AB  JMP LAB82
.LABAD
    ABAD  A9 CE     LDA #&CE
    ABAF  4C 0D AA  JMP ts_error
.LABB2
    ABB2  AC 20 16  LDY ts_state
    ABB5  C0 01     CPY #&01
    ABB7  D0 00     BNE LABB9
.LABB9
    ABB9  AC 66 16  LDY ts_savey
    ABBC  18        CLC
    ABBD  60        RTS
; Empty the output queue (both pointers to &1999).
.ts_reset_queue
    ABBE  48        PHA
    ABBF  A9 99     LDA #&99
    ABC1  8D 1C 16  STA outq_wr
    ABC4  8D 1E 16  STA outq_rd
    ABC7  A9 19     LDA #&19
    ABC9  8D 1D 16  STA outq_wr+1
    ABCC  8D 1F 16  STA outq_rd+1
    ABCF  68        PLA
    ABD0  60        RTS
;------------------------------------------------------------------------------
; BGET CHANNEL 14: NEXT BYTE OF THE DECODED FILE
; Returns C clear with the byte; C set with A=1 or 2 when a new block changes the load
; address (2 = before any data); C set with A=&FE at the end of the file, when "Loaded."
; is printed and the file is closed.
;------------------------------------------------------------------------------
.LABD1
    ABD1  AD 55 16  LDA ts_name
    ABD4  D0 05     BNE LABDB
    ABD6  AD 56 16  LDA ts_name+1
    ABD9  F0 62     BEQ LAC3D
.LABDB
    ABDB  AD 63 16  LDA ts_to_memory
    ABDE  F0 11     BEQ LABF1
    ABE0  AD 61 16  LDA ts_newaddr
    ABE3  F0 0C     BEQ LABF1
    ABE5  A9 00     LDA #&00
    ABE7  8D 61 16  STA ts_newaddr
    ABEA  AD 62 16  LDA ts_pending
    ABED  48        PHA
    ABEE  4C 07 AC  JMP LAC07
.LABF1
    ABF1  8D 49 16  STA ts_comment
    ABF4  8D 4A 16  STA ts_comment+1
    ABF7  20 83 A9  JSR ts_getbyte
    ABFA  B0 36     BCS LAC32
    ABFC  48        PHA
    ABFD  AD 63 16  LDA ts_to_memory
    AC00  F0 05     BEQ LAC07
    AC02  AD 61 16  LDA ts_newaddr
    AC05  D0 15     BNE LAC1C
.LAC07
    AC07  EE 50 16  INC ts_offset
    AC0A  D0 0D     BNE LAC19
    AC0C  EE 51 16  INC ts_offset+1
    AC0F  D0 08     BNE LAC19
    AC11  EE 52 16  INC ts_offset+2
    AC14  D0 03     BNE LAC19
    AC16  EE 53 16  INC ts_offset+3
.LAC19
    AC19  68        PLA
    AC1A  18        CLC
    AC1B  60        RTS
.LAC1C
    AC1C  68        PLA
    AC1D  8D 62 16  STA ts_pending
    AC20  AD 49 16  LDA ts_comment
    AC23  D0 09     BNE LAC2E
    AC25  AD 4A 16  LDA ts_comment+1
    AC28  D0 04     BNE LAC2E
    AC2A  A9 02     LDA #&02
    AC2C  38        SEC
    AC2D  60        RTS
.LAC2E
    AC2E  A9 01     LDA #&01
    AC30  38        SEC
    AC31  60        RTS
.LAC32
    AC32  20 41 AC  JSR LAC41
    AC35  A9 00     LDA #&00
    AC37  8D 55 16  STA ts_name
    AC3A  8D 56 16  STA ts_name+1
.LAC3D
    AC3D  A9 FE     LDA #&FE
    AC3F  38        SEC
    AC40  60        RTS
;------------------------------------------------------------------------------
; End of file: "Loaded. Press RETURN to continue" (if *OPT1 messages on), headers off.
;------------------------------------------------------------------------------
.LAC41
    AC41  AD 94 16  LDA opt1_msgs
    AC44  10 35     BPL LAC7B
    AC46  20 AF A2  JSR print_inline
    AC49  .str '\r\n\x07Loaded.\r\nPress RETURN to continue\x00'
    AC6E  A9 00     LDA #&00
    AC70  8D 70 16  STA &1670
    AC73  8D 71 16  STA &1671
    AC76  A9 92     LDA #&92
    AC78  20 D3 A9  JSR ts_osword
.LAC7B
    AC7B  60        RTS
; *OPT1: store the message level.
.LAC7C
    AC7C  8D 94 16  STA opt1_msgs
    AC7F  60        RTS
; *OPT3: store the "keep name tables" flag.
.LAC80
    AC80  8D 60 16  STA opt3_keep
    AC83  60        RTS
;------------------------------------------------------------------------------
; FINDV (OSFIND). A=0 close: nothing to do. Otherwise open the file named at X/Y for
; reading: reset the decoder, wait for the page ("Searching..."), remember the name.
; Returns handle &0E. Used by *EXEC.
;------------------------------------------------------------------------------
.findv
    AC84  C9 00     CMP #&00
    AC86  D0 01     BNE LAC89
    AC88  60        RTS
.LAC89
    AC89  20 C3 AC  JSR LACC3
    AC8C  20 DF AC  JSR LACDF
    AC8F  A9 0E     LDA #&0E
    AC91  A0 00     LDY #&00
    AC93  60        RTS
;------------------------------------------------------------------------------
; OSFILE 7 (internal): start reading a named file for loading. If the parameter block
; gives a load address (byte 6 = 0) it overrides the file's own. Returns handle &0E.
;------------------------------------------------------------------------------
.LAC94
    AC94  20 C3 AC  JSR LACC3
    AC97  86 CC     STX ts_ptr
    AC99  84 CD     STY ts_ptr+1
    AC9B  A0 06     LDY #&06
    AC9D  B1 CC     LDA (ts_ptr),Y
    AC9F  D0 0D     BNE LACAE
.LACA1
    ACA1  88        DEY
    ACA2  B1 CC     LDA (ts_ptr),Y
    ACA4  99 4A 16  STA ts_comment+1,Y
    ACA7  C0 02     CPY #&02
    ACA9  D0 F6     BNE LACA1
    ACAB  EE 54 16  INC ts_user_load
.LACAE
    ACAE  EE 63 16  INC ts_to_memory
    ACB1  EE 68 16  INC ts_random
    ACB4  A0 00     LDY #&00
    ACB6  B1 CC     LDA (ts_ptr),Y
    ACB8  AA        TAX
    ACB9  C8        INY
    ACBA  B1 CC     LDA (ts_ptr),Y
    ACBC  A8        TAY
    ACBD  20 DF AC  JSR LACDF
    ACC0  A9 0E     LDA #&0E
    ACC2  60        RTS
;------------------------------------------------------------------------------
; Reset the decoder (keeping the name tables if *OPT3,1) and wait for the current page
; with OSWORD &95.
;------------------------------------------------------------------------------
.LACC3
    ACC3  98        TYA
    ACC4  48        PHA
    ACC5  8A        TXA
    ACC6  48        PHA
    ACC7  AD 60 16  LDA opt3_keep
    ACCA  D0 06     BNE LACD2
    ACCC  20 0A A8  JSR ts_init
    ACCF  4C D5 AC  JMP LACD5
.LACD2
    ACD2  20 1C A8  JSR ts_reset
.LACD5
    ACD5  A9 95     LDA #&95
    ACD7  20 D3 A9  JSR ts_osword
    ACDA  68        PLA
    ACDB  AA        TAX
    ACDC  68        PLA
    ACDD  A8        TAY
    ACDE  60        RTS
;------------------------------------------------------------------------------
; Copy the file name at X/Y (quotes removed) to the heap and make it the wanted name.
;------------------------------------------------------------------------------
.LACDF
    ACDF  86 CC     STX ts_ptr
    ACE1  84 CD     STY ts_ptr+1
    ACE3  A0 00     LDY #&00
    ACE5  A2 00     LDX #&00
.LACE7
    ACE7  B1 CC     LDA (ts_ptr),Y
    ACE9  C9 22     CMP #&22                ; '"'
    ACEB  F0 02     BEQ LACEF
    ACED  E8        INX
    ACEE  48        PHA
.LACEF
    ACEF  C8        INY
    ACF0  C9 0D     CMP #&0D
    ACF2  D0 F3     BNE LACE7
    ACF4  8A        TXA
    ACF5  A8        TAY
    ACF6  AE 92 16  LDX heap
    ACF9  86 CC     STX ts_ptr
    ACFB  8E 55 16  STX ts_name
    ACFE  AE 93 16  LDX heap+1
    AD01  86 CD     STX ts_ptr+1
    AD03  8E 56 16  STX ts_name+1
    AD06  18        CLC
    AD07  6D 92 16  ADC heap
    AD0A  8D 92 16  STA heap
    AD0D  90 03     BCC LAD12
    AD0F  EE 93 16  INC heap+1
.LAD12
    AD12  88        DEY
.LAD13
    AD13  68        PLA
    AD14  91 CC     STA (ts_ptr),Y
    AD16  88        DEY
    AD17  10 FA     BPL LAD13
    AD19  60        RTS
;------------------------------------------------------------------------------
; OSFILE 5: READ CATALOGUE INFORMATION: copy the name pointer, load address (base +
; offset), execution address and attributes into the parameter block.
;------------------------------------------------------------------------------
.LAD1A
    AD1A  98        TYA
    AD1B  48        PHA
    AD1C  8A        TXA
    AD1D  48        PHA
    AD1E  20 15 A9  JSR push_frame
    AD21  68        PLA
    AD22  85 CC     STA ts_ptr
    AD24  68        PLA
    AD25  85 CD     STA ts_ptr+1
    AD27  AD 4C 16  LDA ts_load_base
    AD2A  18        CLC
    AD2B  6D 50 16  ADC ts_offset
    AD2E  8D 57 16  STA ts_load
    AD31  AD 4D 16  LDA &164D
    AD34  6D 51 16  ADC ts_offset+1
    AD37  8D 58 16  STA &1658
    AD3A  AD 4E 16  LDA &164E
    AD3D  6D 52 16  ADC ts_offset+2
    AD40  8D 59 16  STA &1659
    AD43  AD 4F 16  LDA &164F
    AD46  6D 53 16  ADC ts_offset+3
    AD49  8D 5A 16  STA &165A
    AD4C  A0 0A     LDY #&0A
.LAD4E
    AD4E  B9 55 16  LDA ts_name,Y
    AD51  91 CC     STA (ts_ptr),Y
    AD53  88        DEY
    AD54  10 F8     BPL LAD4E
    AD56  20 56 A9  JSR pop_frame
    AD59  60        RTS
;------------------------------------------------------------------------------
; OSWORD &7A with a sub-command below &80: decoder information.
; Only codes 0 (returns 0) and 1 (returns the title pointer ts_title) can be reached:
; the BCS after CMP #1 catches every code from 1 up, so the code for 1-3 at &AD78-&AD8A
; is never used, and &167F-&1682 are never written anyway.
;------------------------------------------------------------------------------
.LAD5A
    AD5A  C9 01     CMP #&01
    AD5C  B0 11     BCS LAD6F
    AD5E  F0 18     BEQ LAD78
    AD60  C9 03     CMP #&03
    AD62  B0 1D     BCS LAD81
    AD64  F0 24     BEQ LAD8A
    AD66  A0 00     LDY #&00
    AD68  98        TYA
    AD69  91 F0     STA (osw_x),Y
    AD6B  C8        INY
    AD6C  91 F0     STA (osw_x),Y
    AD6E  60        RTS
.LAD6F
    AD6F  AE 64 16  LDX ts_title
    AD72  AD 65 16  LDA ts_title+1
    AD75  4C 90 AD  JMP LAD90
.LAD78
    AD78  AE 49 16  LDX ts_comment
    AD7B  AD 4A 16  LDA ts_comment+1
    AD7E  4C 90 AD  JMP LAD90
.LAD81
    AD81  AE 7F 16  LDX &167F
    AD84  AD 80 16  LDA &1680
    AD87  4C 90 AD  JMP LAD90
.LAD8A
    AD8A  AE 81 16  LDX &1681
    AD8D  AD 82 16  LDA &1682
.LAD90
    AD90  A0 01     LDY #&01
    AD92  91 F0     STA (osw_x),Y
    AD94  8A        TXA
    AD95  88        DEY
    AD96  91 F0     STA (osw_x),Y
    AD98  60        RTS
;------------------------------------------------------------------------------
; <TXT>  TELETEXT FORMAT
; Sets up the name tables for data received from teletext, then starts a block (<DSB>):
;   - every lone name with correct (odd) parity decodes to itself with bit 7 removed
;   - lone &FE becomes <ULB> and lone &E0 <URB> (the manual says the other way round)
;   - escaped &FE and &E0 decode to &7E and &60
;   - every command moves to the single pass used here
;   - escaped &C2 ("B" with its parity bit) and &46 become <DSB>; escaped &E3 ("c"
;     with parity) becomes <DEB> without its operand
;   - numbers are now ASCII hex
; <TXT> also sets ts_random: the next block is found with HEAD OF CHAIN.
;------------------------------------------------------------------------------
.ts_TXT
    AD99  EE 68 16  INC ts_random           ; <TXT>: blocks may arrive in any order
; <TXO>: as <TXT> without that.
.ts_TXO
    AD9C  A0 00     LDY #&00
.LAD9E
    AD9E  B9 9A 0F  LDA lone_kind,Y
    ADA1  C9 01     CMP #&01
    ADA3  D0 06     BNE LADAB
    ADA5  98        TYA
    ADA6  29 7F     AND #&7F
    ADA8  99 9A 10  STA lone_lo,Y
.LADAB
    ADAB  C8        INY
    ADAC  D0 F0     BNE LAD9E
    ADAE  A2 FE     LDX #&FE
    ADB0  A0 E0     LDY #&E0
    ADB2  A9 12     LDA #&12
    ADB4  9D 9A 0F  STA lone_kind,X
    ADB7  99 9A 0F  STA lone_kind,Y
    ADBA  A9 B4     LDA #&B4
    ADBC  9D 9A 10  STA lone_lo,X
    ADBF  A9 B1     LDA #&B1
    ADC1  9D 9A 11  STA lone_hi,X
    ADC4  A9 BD     LDA #&BD
    ADC6  99 9A 10  STA lone_lo,Y
    ADC9  A9 B1     LDA #&B1
    ADCB  99 9A 11  STA lone_hi,Y
    ADCE  A9 01     LDA #&01
    ADD0  9D 9A 12  STA esc_kind,X
    ADD3  99 9A 12  STA esc_kind,Y
    ADD6  A9 7E     LDA #&7E
    ADD8  9D 9A 13  STA esc_lo,X
    ADDB  A9 60     LDA #&60
    ADDD  99 9A 13  STA esc_lo,Y
    ADE0  A0 00     LDY #&00
.LADE2
    ADE2  B9 9A 12  LDA esc_kind,Y
    ADE5  C9 11     CMP #&11
    ADE7  D0 05     BNE LADEE
    ADE9  A9 12     LDA #&12
    ADEB  99 9A 12  STA esc_kind,Y
.LADEE
    ADEE  C8        INY
    ADEF  D0 F1     BNE LADE2
    ADF1  EE 7E 16  INC ts_hexmode
    ADF4  A0 C2     LDY #&C2
    ADF6  A9 10     LDA #&10
    ADF8  99 9A 12  STA esc_kind,Y
    ADFB  A0 46     LDY #&46
    ADFD  99 9A 12  STA esc_kind,Y
    AE00  A9 20     LDA #&20
    AE02  99 9A 13  STA esc_lo,Y
    AE05  A0 C2     LDY #&C2
    AE07  99 9A 13  STA esc_lo,Y
    AE0A  A9 AE     LDA #&AE
    AE0C  99 9A 14  STA esc_hi,Y
    AE0F  A0 46     LDY #&46
    AE11  99 9A 14  STA esc_hi,Y
    AE14  A0 E3     LDY #&E3
    AE16  A9 9A     LDA #&9A
    AE18  99 9A 13  STA esc_lo,Y
    AE1B  A9 B2     LDA #&B2
    AE1D  99 9A 14  STA esc_hi,Y
; Escaped &C2 / &46 enter here: <DSB> within <TXT> data.
.LAE20
    AE20  20 2F AE  JSR ts_DSB
    AE23  AD 20 16  LDA ts_state
    AE26  F0 05     BEQ LAE2D
    AE28  A9 02     LDA #&02
    AE2A  8D 20 16  STA ts_state
.LAE2D
    AE2D  18        CLC
    AE2E  60        RTS
;------------------------------------------------------------------------------
; <DSB>  START OF BLOCK [block number] [number of blocks]
; Ordered files: a block other than the one expected is skipped (ask for the next page).
; Random-order files: a block already received (bit set in ts_block_map) is skipped.
;------------------------------------------------------------------------------
.ts_DSB
    AE2F  A9 01     LDA #&01
    AE31  8D 20 16  STA ts_state
    AE34  A9 00     LDA #&00
    AE36  8D 69 16  STA ts_blk_check
    AE39  8D 6A 16  STA &166A
    AE3C  20 12 AB  JSR ts_number           ; number of operands
    AE3F  C9 01     CMP #&01
    AE41  08        PHP
    AE42  30 48     BMI LAE8C
    AE44  A9 67     LDA #&67                ; block number into ts_block_no
    AE46  85 CC     STA ts_ptr
    AE48  A9 16     LDA #&16
    AE4A  85 CD     STA ts_ptr+1
    AE4C  20 6D AF  JSR ts_read_value
    AE4F  E0 00     CPX #&00
    AE51  F0 39     BEQ LAE8C
    AE53  AE 68 16  LDX ts_random
    AE56  D0 34     BNE LAE8C
    AE58  AD 67 16  LDA ts_block_no         ; random order: has this block been seen?
    AE5B  4A        LSR A
    AE5C  4A        LSR A
    AE5D  4A        LSR A
    AE5E  A8        TAY
    AE5F  AA        TAX
.LAE60
    AE60  C0 00     CPY #&00
    AE62  F0 0C     BEQ LAE70
    AE64  88        DEY
    AE65  B9 25 16  LDA ts_block_map,Y
    AE68  C9 FF     CMP #&FF
    AE6A  F0 F4     BEQ LAE60
.LAE6C
    AE6C  68        PLA
    AE6D  4C D3 AE  JMP LAED3
.LAE70
    AE70  8A        TXA
    AE71  A8        TAY
    AE72  AD 67 16  LDA ts_block_no
    AE75  29 07     AND #&07
    AE77  AA        TAX
    AE78  A9 00     LDA #&00
    AE7A  E0 00     CPX #&00
    AE7C  F0 05     BEQ LAE83
.LAE7E
    AE7E  38        SEC
    AE7F  2A        ROL A
    AE80  CA        DEX
    AE81  D0 FB     BNE LAE7E
.LAE83
    AE83  85 CE     STA ts_tmp
    AE85  39 25 16  AND ts_block_map,Y
    AE88  C5 CE     CMP ts_tmp
    AE8A  D0 E0     BNE LAE6C
.LAE8C
    AE8C  AD 23 16  LDA ts_blocks_total     ; block beyond the total?
    AE8F  38        SEC
    AE90  ED 67 16  SBC ts_block_no
    AE93  90 D7     BCC LAE6C
    AE95  28        PLP
    AE96  F0 13     BEQ LAEAB
    AE98  30 11     BMI LAEAB
    AE9A  AD 23 16  LDA ts_blocks_total     ; number of blocks in the file
    AE9D  8D 6E 16  STA ts_total_save
    AEA0  A9 23     LDA #&23
    AEA2  85 CC     STA ts_ptr
    AEA4  A9 16     LDA #&16
    AEA6  85 CD     STA ts_ptr+1
    AEA8  20 6D AF  JSR ts_read_value
.LAEAB
    AEAB  AD 67 16  LDA ts_block_no
    AEAE  4A        LSR A
    AEAF  4A        LSR A
    AEB0  4A        LSR A
    AEB1  A8        TAY
    AEB2  AD 67 16  LDA ts_block_no
    AEB5  29 07     AND #&07
    AEB7  AA        TAX
    AEB8  A9 01     LDA #&01
    AEBA  E0 00     CPX #&00
    AEBC  F0 04     BEQ LAEC2
.LAEBE
    AEBE  0A        ASL A
    AEBF  CA        DEX
    AEC0  D0 FC     BNE LAEBE
.LAEC2
    AEC2  39 25 16  AND ts_block_map,Y
    AEC5  D0 0C     BNE LAED3
    AEC7  A9 01     LDA #&01                ; a wanted block: start decoding it
    AEC9  8D 20 16  STA ts_state
    AECC  A9 81     LDA #&81
.LAECE
    AECE  20 D3 A9  JSR ts_osword
    AED1  18        CLC
    AED2  60        RTS
.LAED3
    AED3  AD 6E 16  LDA ts_total_save       ; not wanted: go and get the next page
    AED6  8D 23 16  STA ts_blocks_total
    AED9  A9 00     LDA #&00
    AEDB  8D 20 16  STA ts_state
    AEDE  AD 68 16  LDA ts_random
    AEE1  F0 05     BEQ LAEE8
    AEE3  A9 88     LDA #&88
    AEE5  4C CE AE  JMP LAECE
.LAEE8
    AEE8  A9 86     LDA #&86
    AEEA  4C CE AE  JMP LAECE
;------------------------------------------------------------------------------
; <DLA>  LOAD ADDRESS (absolute), unless the user gave a load address. Resets the offset.
;------------------------------------------------------------------------------
.ts_DLA
    AEED  AD 54 16  LDA ts_user_load
    AEF0  D0 1A     BNE LAF0C
    AEF2  A9 4C     LDA #&4C
    AEF4  85 CC     STA ts_ptr
    AEF6  A9 16     LDA #&16
    AEF8  85 CD     STA ts_ptr+1
    AEFA  A9 00     LDA #&00
    AEFC  A0 03     LDY #&03
.LAEFE
    AEFE  91 CC     STA (ts_ptr),Y
    AF00  99 50 16  STA ts_offset,Y
    AF03  88        DEY
    AF04  10 F8     BPL LAEFE
    AF06  20 6D AF  JSR ts_read_value
    AF09  EE 61 16  INC ts_newaddr
.LAF0C
    AF0C  18        CLC
    AF0D  60        RTS
; <DXA>  EXECUTION ADDRESS (absolute).
.ts_DXA
    AF0E  A9 5B     LDA #&5B
    AF10  85 CC     STA ts_ptr
    AF12  A9 16     LDA #&16
