    B2CD  EE 22 16  INC ts_blocks_done      ; count the block
    B2D0  AD 23 16  LDA ts_blocks_total
    B2D3  CD 22 16  CMP ts_blocks_done
    B2D6  F0 36     BEQ LB30E               ; all blocks received?
    B2D8  A9 00     LDA #&00
    B2DA  8D 20 16  STA ts_state
    B2DD  AD 68 16  LDA ts_random
    B2E0  F0 05     BEQ LB2E7
    B2E2  A9 88     LDA #&88
    B2E4  4C E9 B2  JMP LB2E9
.LB2E7
    B2E7  A9 86     LDA #&86
.LB2E9
    B2E9  20 D3 A9  JSR ts_osword
    B2EC  AD 67 16  LDA ts_block_no
    B2EF  4A        LSR A
    B2F0  4A        LSR A
    B2F1  4A        LSR A
    B2F2  A8        TAY
    B2F3  AD 67 16  LDA ts_block_no
    B2F6  29 07     AND #&07
    B2F8  AA        TAX
    B2F9  A9 01     LDA #&01
    B2FB  E0 00     CPX #&00
    B2FD  F0 04     BEQ LB303
.LB2FF
    B2FF  0A        ASL A
    B300  CA        DEX
    B301  D0 FC     BNE LB2FF
.LB303
    B303  19 25 16  ORA ts_block_map,Y
    B306  99 25 16  STA ts_block_map,Y
    B309  EE 67 16  INC ts_block_no
.LB30C
    B30C  18        CLC
    B30D  60        RTS
.LB30E
    B30E  38        SEC
    B30F  60        RTS
; Print the stored comment text.
.LB310
    B310  20 15 A9  JSR push_frame
    B313  AD 49 16  LDA ts_comment
    B316  85 CC     STA ts_ptr
    B318  AD 4A 16  LDA ts_comment+1
    B31B  85 CD     STA ts_ptr+1
    B31D  A0 00     LDY #&00
    B31F  B1 CC     LDA (ts_ptr),Y
    B321  AA        TAX
.LB322
    B322  C8        INY
    B323  B1 CC     LDA (ts_ptr),Y
    B325  20 E3 FF  JSR OSASCI
    B328  CA        DEX
    B329  D0 F7     BNE LB322
    B32B  20 56 A9  JSR pop_frame
    B32E  60        RTS
;------------------------------------------------------------------------------
; TERMINAL MODE ENTRY (language entry, via the JMP at &8000)
; Set up MODE 7, the function keys and BRKV, make Telesoft the filing system, start
; rolling headers on the top row, allocate page buffers in user memory, request the
; index page, then run the main loop.
;------------------------------------------------------------------------------
.terminal_entry
    B32F  58        CLI
    B330  20 07 BC  JSR LBC07               ; (does nothing)
    B333  A9 16     LDA #&16
    B335  20 EE FF  JSR OSWRCH              ; VDU 22: MODE
    B338  A9 07     LDA #&07
    B33A  20 EE FF  JSR OSWRCH              ; VDU 7: BEL
    B33D  20 1B B4  JSR LB41B               ; function and cursor keys produce codes; cursor on
    B340  20 02 B4  JSR LB402               ; current filing system
    B343  A5 32     LDA t_fs
    B345  C9 06     CMP #&06
    B347  F0 03     BEQ LB34C
    B349  20 7B B4  JSR LB47B               ; make TFS the filing system if it isn't
.LB34C
    B34C  20 22 B4  JSR LB422               ; channel 0, buffers, index page, rolling headers
    B34F  20 0B B4  JSR LB40B               ; remember the previous language and filing system
    B352  20 32 B5  JSR LB532               ; errors come to terminal_brk_handler
    B355  4C 8E B3  JMP main_loop
; Held page: show "Press SPACE to continue" and wait.
.LB358
    B358  20 3A B7  JSR status_line_inline
    B35B  .str ' *** Press SPACE to continue           '
    B382  EA        NOP
;------------------------------------------------------------------------------
; Count down the delay that stops wild-card pages replacing each other too fast.
;------------------------------------------------------------------------------
.LB383
    B383  A9 13     LDA #&13
    B385  20 F4 FF  JSR OSBYTE              ; OSBYTE &13: wait for vertical sync
    B388  C6 35     DEC t_delay
    B38A  10 02     BPL main_loop
    B38C  E6 35     INC t_delay
;------------------------------------------------------------------------------
; MAIN LOOP: handle a key if one was pressed, else show a new copy of the page when it
; arrives. Pages are fetched into the buffer at &7800 and copied to the screen from there.
;------------------------------------------------------------------------------
.main_loop
    B38E  20 E3 B3  JSR read_key
    B391  B0 1F     BCS LB3B2               ; ESCAPE
    B393  F0 03     BEQ LB398
    B395  4C 3B B8  JMP terminal_dispatch_key; a key: dispatch it
.LB398
    B398  24 0B     BIT t_hold              ; held?
    B39A  70 BC     BVS LB358
    B39C  A5 35     LDA t_delay             ; still in the wild-card delay?
    B39E  D0 E3     BNE LB383
    B3A0  20 79 B5  JSR LB579               ; TEST ARRIVED
    B3A3  10 E9     BPL main_loop
    B3A5  20 9B B5  JSR LB59B               ; new page: fetch its flags and number, TRANSFER it to &7800, unlock
.LB3A8
    B3A8  20 DA B5  JSR draw_page           ; draw it, then wait ~2.5 s before showing another page
    B3AB  A9 7F     LDA #&7F
    B3AD  85 35     STA t_delay
    B3AF  4C 8E B3  JMP main_loop
; ESCAPE: acknowledge it and redraw.
.LB3B2
    B3B2  A9 7E     LDA #&7E
    B3B4  20 F4 FF  JSR OSBYTE              ; OSBYTE &7E: acknowledge ESCAPE
    B3B7  4C 86 BB  JMP LBB86
; After an error: "*** Press ESCAPE to continue".
.LB3BA
    B3BA  20 37 B7  JSR clear_status_inline
    B3BD  .str '\x88*** Press ESCAPE to continue'
    B3DA  EA        NOP
.LB3DB
    B3DB  20 E3 B3  JSR read_key
    B3DE  90 FB     BCC LB3DB
    B3E0  4C B2 B3  JMP LB3B2
;------------------------------------------------------------------------------
; Poll the keyboard (no wait). C set: ESCAPE. Z set: no key. Otherwise A = key.
;------------------------------------------------------------------------------
.read_key
    B3E3  A9 81     LDA #&81
    B3E5  A2 00     LDX #&00
    B3E7  A0 00     LDY #&00
    B3E9  20 F4 FF  JSR OSBYTE
    B3EC  8A        TXA
    B3ED  90 08     BCC LB3F7
    B3EF  C0 1B     CPY #&1B
    B3F1  38        SEC
    B3F2  F0 03     BEQ LB3F7
    B3F4  18        CLC
    B3F5  A9 00     LDA #&00
.LB3F7
    B3F7  60        RTS
; OSWORD &7A with the block at t_osw (zero page &0C).
.t_osword
    B3F8  A9 7A     LDA #&7A
    B3FA  A2 0C     LDX #&0C
    B3FC  A0 00     LDY #&00
    B3FE  20 F1 FF  JSR OSWORD
    B401  60        RTS
; t_fs = current filing system number.
.LB402
    B402  A9 00     LDA #&00
    B404  A8        TAY
    B405  20 DA FF  JSR OSARGS
    B408  85 32     STA t_fs
    B40A  60        RTS
;------------------------------------------------------------------------------
; Read the previous language and filing system (OSWORD &7A &91).
;------------------------------------------------------------------------------
.LB40B
    B40B  A9 91     LDA #&91
    B40D  85 0C     STA t_osw
    B40F  20 F8 B3  JSR t_osword            ; OSWORD &7A &91: read previous language
    B412  A5 0D     LDA t_osw+1
    B414  85 31     STA t_prev_lang
    B416  A5 0E     LDA t_osw+2
    B418  85 32     STA t_fs
    B41A  60        RTS
;------------------------------------------------------------------------------
; Function keys &90+, cursor keys as codes, SHIFT+function keys &9A+; cursor off.
;------------------------------------------------------------------------------
.LB41B
    B41B  20 3D B5  JSR LB53D
    B41E  20 5E B5  JSR LB55E
    B421  60        RTS
;------------------------------------------------------------------------------
; Start-up: channel 1, allocate page buffers (OSWORD &9B), request the index page,
; rolling headers on, clear the state and the page buffer at &7800-&7BFF.
;------------------------------------------------------------------------------
.LB422
    B422  A9 8B     LDA #&8B
    B424  85 0C     STA t_osw
    B426  A9 00     LDA #&00
    B428  85 0D     STA t_osw+1
    B42A  20 F8 B3  JSR t_osword            ; OSWORD &7A &8B: SELECT CHANNEL
    B42D  20 5F B7  JSR LB75F
    B430  20 CF B4  JSR LB4CF
    B433  20 18 B5  JSR LB518
    B436  A9 01     LDA #&01
    B438  85 0A     STA t_link
    B43A  A9 00     LDA #&00
    B43C  85 35     STA t_delay
    B43E  85 09     STA t_reveal
    B440  85 0B     STA t_hold
    B442  85 34     STA t_flags
    B444  A9 57     LDA #&57                ; "Waiting" shown as the page number until the first page arrives
    B446  85 2A     STA &2A
    B448  A9 61     LDA #&61
    B44A  85 2B     STA &2B
    B44C  A9 69     LDA #&69
    B44E  85 2C     STA &2C
    B450  A9 74     LDA #&74
    B452  85 2D     STA &2D
    B454  A9 69     LDA #&69
    B456  85 2E     STA &2E
    B458  A9 6E     LDA #&6E
    B45A  85 2F     STA &2F
    B45C  A9 67     LDA #&67
    B45E  85 30     STA &30
    B460  A9 00     LDA #&00
    B462  85 00     STA t_ptr
    B464  A9 78     LDA #&78
    B466  85 01     STA t_ptr+1
    B468  A0 00     LDY #&00
.LB46A
    B46A  A9 20     LDA #&20
    B46C  91 00     STA (t_ptr),Y
    B46E  E6 00     INC t_ptr
    B470  D0 02     BNE LB474
    B472  E6 01     INC t_ptr+1
.LB474
    B474  A5 01     LDA t_ptr+1
    B476  C9 7C     CMP #&7C                ; '|'
    B478  D0 F0     BNE LB46A
    B47A  60        RTS
; Service &12 with Y=6: make TFS the filing system.
.LB47B
    B47B  A9 8F     LDA #&8F
    B47D  A2 12     LDX #&12
    B47F  A0 06     LDY #&06
    B481  20 F4 FF  JSR OSBYTE
    B484  60        RTS
;------------------------------------------------------------------------------
; Reselect the previous filing system (t_fs): 1/2 tape at 1200/300 baud, 3 ROM,
; 4 disc (*DISK), others by service &12.
;------------------------------------------------------------------------------
.LB485
    B485  A4 32     LDY t_fs
    B487  C0 04     CPY #&04
    B489  10 1C     BPL LB4A7
    B48B  C0 03     CPY #&03
    B48D  D0 06     BNE LB495
    B48F  A9 8D     LDA #&8D
    B491  20 F4 FF  JSR OSBYTE              ; OSBYTE &8D: select ROM filing system
    B494  60        RTS
.LB495
    B495  A9 8C     LDA #&8C
    B497  C0 02     CPY #&02
    B499  D0 06     BNE LB4A1
    B49B  A2 03     LDX #&03
    B49D  20 F4 FF  JSR OSBYTE
    B4A0  60        RTS
.LB4A1
    B4A1  A2 0C     LDX #&0C
    B4A3  20 F4 FF  JSR OSBYTE
    B4A6  60        RTS
.LB4A7
    B4A7  C0 04     CPY #&04
    B4A9  D0 1C     BNE LB4C7
    B4AB  A9 44     LDA #&44
    B4AD  85 0C     STA t_osw
    B4AF  A9 49     LDA #&49
    B4B1  85 0D     STA t_osw+1
    B4B3  A9 53     LDA #&53
    B4B5  85 0E     STA t_osw+2
    B4B7  A9 4B     LDA #&4B
    B4B9  85 0F     STA t_osw+3
    B4BB  A9 0D     LDA #&0D
    B4BD  85 10     STA t_osw+4
    B4BF  A2 0C     LDX #&0C
    B4C1  A0 00     LDY #&00
    B4C3  20 F7 FF  JSR OSCLI
    B4C6  60        RTS
.LB4C7
    B4C7  A9 8F     LDA #&8F
    B4C9  A2 12     LDX #&12
    B4CB  20 F4 FF  JSR OSBYTE
    B4CE  60        RTS
;------------------------------------------------------------------------------
; SHIFT f1, f4 and start-up: request the index page (OSWORD &A0: the initial page from
; the service data, else x00) and show "Waiting for page". The template at &B50A is a
; FETCH of page x00 with any sub-code.
;------------------------------------------------------------------------------
.LB4CF
    B4CF  A9 FF     LDA #&FF
    B4D1  85 0A     STA t_link
    B4D3  A2 07     LDX #&07
.LB4D5
    B4D5  BD 0A B5  LDA &B50A,X
    B4D8  95 0C     STA t_osw,X
    B4DA  E0 00     CPX #&00
    B4DC  F0 02     BEQ LB4E0
    B4DE  95 1F     STA &1F,X
.LB4E0
    B4E0  CA        DEX
    B4E1  10 F2     BPL LB4D5
    B4E3  A9 A0     LDA #&A0
    B4E5  85 0C     STA t_osw
    B4E7  20 F8 B3  JSR t_osword            ; OSWORD &7A &A0: decode date/time
    B4EA  20 A9 B6  JSR LB6A9
; "*** Waiting for page " then the page number.
.LB4ED
    B4ED  20 37 B7  JSR clear_status_inline
    B4F0  .str ' *** Waiting for page '
    B506  EA        NOP
    B507  4C AA B6  JMP LB6AA
    B50A  .db 85 FF 00 00 FF FF FF FF                          ; ........
; Rolling headers off.
.LB512
    B512  A9 00     LDA #&00
    B514  48        PHA
    B515  4C 1B B5  JMP LB51B
;------------------------------------------------------------------------------
; Rolling headers on: OSWORD &92 to &7C08, the top row of the MODE 7 screen.
;------------------------------------------------------------------------------
.LB518
    B518  A9 7C     LDA #&7C
    B51A  48        PHA
.LB51B
    B51B  A9 92     LDA #&92
    B51D  85 0C     STA t_osw
    B51F  68        PLA
    B520  85 0E     STA t_osw+2
    B522  A9 08     LDA #&08
    B524  85 0D     STA t_osw+1
    B526  A9 FF     LDA #&FF
    B528  85 10     STA t_osw+4
    B52A  A9 FF     LDA #&FF
    B52C  85 0F     STA t_osw+3
    B52E  20 F8 B3  JSR t_osword
    B531  60        RTS
; BRKV := terminal_brk_handler
.LB532
    B532  A9 67     LDA #&67
    B534  8D 02 02  STA BRKV
    B537  A9 B7     LDA #&B7
    B539  8D 03 02  STA BRKV+1
    B53C  60        RTS
;------------------------------------------------------------------------------
; Function keys give &90-&99, cursor keys &87-&8B, SHIFT+function keys &9A-&A3.
;------------------------------------------------------------------------------
.LB53D
    B53D  A2 90     LDX #&90
    B53F  A0 00     LDY #&00
    B541  A9 E1     LDA #&E1
    B543  20 F4 FF  JSR OSBYTE              ; OSBYTE &E1: set base code for function keys
    B546  A9 04     LDA #&04
    B548  A2 01     LDX #&01
    B54A  A0 00     LDY #&00
    B54C  20 F4 FF  JSR OSBYTE              ; OSBYTE &04: cursor key mode (X=1: cursor keys return codes &87-&8B)
    B54F  A9 E2     LDA #&E2
    B551  A2 9A     LDX #&9A
    B553  A0 00     LDY #&00
    B555  20 F4 FF  JSR OSBYTE              ; OSBYTE &E2: set base code for SHIFT+function keys
    B558  60        RTS
; Cursor on (VDU 23,1,1,0;0;0;).
.LB559
    B559  A0 01     LDY #&01
    B55B  4C 60 B5  JMP LB560
; Cursor off (VDU 23,1,0,0;0;0;).
.LB55E
    B55E  A0 00     LDY #&00
.LB560
    B560  A9 17     LDA #&17
    B562  20 EE FF  JSR OSWRCH              ; VDU 23: VDU 23 (define/cursor)
    B565  A9 01     LDA #&01
    B567  20 EE FF  JSR OSWRCH              ; VDU 1
    B56A  98        TYA
    B56B  20 EE FF  JSR OSWRCH
    B56E  A9 00     LDA #&00
    B570  A0 07     LDY #&07
.LB572
    B572  20 EE FF  JSR OSWRCH              ; VDU 0
    B575  88        DEY
    B576  D0 FA     BNE LB572
    B578  60        RTS
;------------------------------------------------------------------------------
; OSWORD &7A &89 TEST ARRIVED: N set (from BIT) if a new page has arrived.
;------------------------------------------------------------------------------
.LB579
    B579  A9 89     LDA #&89
    B57B  85 0C     STA t_osw
    B57D  20 F8 B3  JSR t_osword            ; OSWORD &7A &89: TEST ARRIVED
    B580  24 0D     BIT t_osw+1
    B582  60        RTS
    B583  .db A9 8C 85 0C 20 F8 B3 24 0D 50 03 A9 FF 60 24 34  ; .... ..$.P...`$4
    B593  .db 70 03 A9 FF 60 A9 00 60                          ; p...`..`
;------------------------------------------------------------------------------
; Get the new page: its checksum flags, its page number (shown with COPY), then TRANSFER
; it to &7800 (in this machine: high address from OSBYTE &82) and UNLOCK it.
;------------------------------------------------------------------------------
.LB59B
    B59B  A9 8C     LDA #&8C
    B59D  85 0C     STA t_osw
    B59F  20 F8 B3  JSR t_osword            ; OSWORD &7A &8C: read page flags
    B5A2  A5 0D     LDA t_osw+1
    B5A4  85 34     STA t_flags
    B5A6  A9 A3     LDA #&A3
    B5A8  85 0C     STA t_osw
    B5AA  20 F8 B3  JSR t_osword            ; OSWORD &7A &A3: read page number
    B5AD  A0 01     LDY #&01
.LB5AF
    B5AF  B9 0C 00  LDA t_osw,Y
    B5B2  99 29 00  STA t_shown_page,Y
    B5B5  C8        INY
    B5B6  C0 08     CPY #&08
    B5B8  D0 F5     BNE LB5AF
    B5BA  A9 8F     LDA #&8F
    B5BC  85 0C     STA t_osw
    B5BE  A9 78     LDA #&78
    B5C0  85 0E     STA t_osw+2
    B5C2  A9 00     LDA #&00
    B5C4  85 0D     STA t_osw+1
    B5C6  A9 82     LDA #&82
    B5C8  20 F4 FF  JSR OSBYTE              ; OSBYTE &82: read machine high order address
    B5CB  84 10     STY t_osw+4
    B5CD  86 0F     STX t_osw+3
    B5CF  20 F8 B3  JSR t_osword
    B5D2  A9 8A     LDA #&8A
    B5D4  85 0C     STA t_osw
    B5D6  4C F8 B3  JMP t_osword            ; OSWORD &7A &8A: UNLOCK PAGE
    B5D9  .db 60                                               ; `
;------------------------------------------------------------------------------
; DRAW THE PAGE: rows 1-23 from the buffer at &7800 (row 0 shows the rolling header).
; When revealing (t_reveal), the conceal code &98 is replaced by a space so the hidden
; text shows. Then report the checksum state at the bottom right:
;   check word present + matched : nothing
;   check word present, mismatch : "Bad data"
;   no check word                : "No check"
;------------------------------------------------------------------------------
.draw_page
    B5DA  A9 1E     LDA #&1E
    B5DC  20 EE FF  JSR OSWRCH              ; VDU 30: cursor home
    B5DF  20 AA B6  JSR LB6AA
    B5E2  20 3A B7  JSR status_line_inline
    B5E5  .str '\x1e\n'
    B5E7  EA        NOP
    B5E8  A9 28     LDA #&28                ; start at row 1 of the buffer
    B5EA  85 00     STA t_ptr
    B5EC  A9 78     LDA #&78
    B5EE  85 01     STA t_ptr+1
    B5F0  A0 00     LDY #&00
.LB5F2
    B5F2  B1 00     LDA (t_ptr),Y
    B5F4  C9 98     CMP #&98                ; conceal code?
    B5F6  D0 06     BNE LB5FE
    B5F8  A6 09     LDX t_reveal
    B5FA  F0 02     BEQ LB5FE
    B5FC  A9 20     LDA #&20
.LB5FE
    B5FE  09 80     ORA #&80                ; MODE 7 code
    B600  20 EE FF  JSR OSWRCH
    B603  E6 00     INC t_ptr
    B605  A5 00     LDA t_ptr
    B607  C9 C0     CMP #&C0
    B609  D0 06     BNE LB611
    B60B  A6 01     LDX t_ptr+1
    B60D  E0 7B     CPX #&7B                ; '{'
    B60F  F0 08     BEQ LB619
.LB611
    B611  AA        TAX
    B612  D0 DE     BNE LB5F2
    B614  E6 01     INC t_ptr+1
    B616  4C F2 B5  JMP LB5F2
.LB619
    B619  24 34     BIT t_flags
    B61B  30 32     BMI LB64F
    B61D  70 5E     BVS LB67D
    B61F  20 37 B7  JSR clear_status_inline
    B622  .str '                               No check'
    B649  EA        NOP
    B64A  60        RTS
.LB64B
    B64B  20 0B B7  JSR clear_status_line
    B64E  60        RTS
.LB64F
    B64F  70 FA     BVS LB64B
    B651  20 37 B7  JSR clear_status_inline
    B654  .str '                               Bad data'
    B67B  EA        NOP
    B67C  60        RTS
.LB67D
    B67D  20 37 B7  JSR clear_status_inline
    B680  .str '                               No check'
    B6A7  EA        NOP
    B6A8  60        RTS
.LB6A9
    B6A9  60        RTS
; Print the requested page number from t_last_page.
.LB6AA
    B6AA  A2 06     LDX #&06
.LB6AC
    B6AC  B5 20     LDA t_last_page,X
    B6AE  95 0D     STA t_osw+1,X
    B6B0  CA        DEX
    B6B1  10 F9     BPL LB6AC
;------------------------------------------------------------------------------
; Print the 7 digits at t_osw+1: "#" for a wild digit, a space before the sub-code, and
; the sub-code left out if it is all wild.
;------------------------------------------------------------------------------
.LB6B3
    B6B3  A0 00     LDY #&00
    B6B5  A2 23     LDX #&23
    B6B7  20 F6 B6  JSR LB6F6
    B6BA  C8        INY
    B6BB  20 F6 B6  JSR LB6F6
    B6BE  C8        INY
    B6BF  20 F6 B6  JSR LB6F6
    B6C2  C8        INY
    B6C3  A2 2F     LDX #&2F
    B6C5  B9 10 00  LDA t_osw+4,Y
    B6C8  10 11     BPL LB6DB
    B6CA  B9 0F 00  LDA t_osw+3,Y
    B6CD  10 0C     BPL LB6DB
    B6CF  B9 0E 00  LDA t_osw+2,Y
    B6D2  10 07     BPL LB6DB
    B6D4  B9 0D 00  LDA t_osw+1,Y
    B6D7  10 02     BPL LB6DB
    B6D9  A2 20     LDX #&20
.LB6DB
    B6DB  20 F6 B6  JSR LB6F6
    B6DE  E0 20     CPX #&20
    B6E0  F0 02     BEQ LB6E4
    B6E2  A2 23     LDX #&23
.LB6E4
