; Blank row 24.
.clear_status_line
    B70B  20 3A B7  JSR status_line_inline
    B70E  .str '                                       '
    B735  EA        NOP
    B736  60        RTS
; Blank row 24, then print the following string there.
.clear_status_inline
    B737  20 0B B7  JSR clear_status_line
;------------------------------------------------------------------------------
; PRINT INLINE TEXT ON ROW 24: TAB(0,24), then print the bytes after the JSR up to an &EA
; byte, which is then executed as a NOP.
;------------------------------------------------------------------------------
.status_line_inline
    B73A  A9 1F     LDA #&1F
    B73C  20 EE FF  JSR OSWRCH              ; VDU 31: TAB(x,y)
    B73F  A9 00     LDA #&00
    B741  A8        TAY
    B742  20 EE FF  JSR OSWRCH              ; VDU 0
    B745  68        PLA
    B746  85 00     STA t_ptr
    B748  68        PLA
    B749  85 01     STA t_ptr+1
    B74B  A9 18     LDA #&18                ; 24 is the row for the VDU 31 sequence
.LB74D
    B74D  20 EE FF  JSR OSWRCH              ; (first time round: the row number)
    B750  E6 00     INC t_ptr
    B752  D0 02     BNE LB756
    B754  E6 01     INC t_ptr+1
.LB756
    B756  B1 00     LDA (t_ptr),Y
    B758  C9 EA     CMP #&EA
    B75A  D0 F1     BNE LB74D
    B75C  6C 00 00  JMP (t_ptr)
; OSWORD &7A &9B: allocate page buffers from PAGE.
.LB75F
    B75F  A9 9B     LDA #&9B
    B761  85 0C     STA t_osw
    B763  20 F8 B3  JSR t_osword            ; OSWORD &7A &9B
    B766  60        RTS
;------------------------------------------------------------------------------
; TERMINAL MODE BRK HANDLER: reset the stack, reselect TFS, print the error message,
; then wait for ESCAPE.
