    B769  9A        TXS
    B76A  20 7B B4  JSR LB47B
    B76D  20 1B B4  JSR LB41B
    B770  A9 0D     LDA #&0D
    B772  20 E3 FF  JSR OSASCI              ; VDU 13: carriage return
    B775  A0 01     LDY #&01
.LB777
    B777  B1 FD     LDA (brk_ptr),Y
    B779  F0 06     BEQ LB781
    B77B  20 E3 FF  JSR OSASCI
    B77E  C8        INY
    B77F  D0 F6     BNE LB777
.LB781
    B781  A9 0D     LDA #&0D
    B783  20 E3 FF  JSR OSASCI              ; VDU 13: carriage return
    B786  4C BA B3  JMP LB3BA
