    BB59  85 00     STA t_ptr
    BB5B  A9 BB     LDA #&BB
    BB5D  85 01     STA t_ptr+1
    BB5F  A0 04     LDY #&04
.LBB61
    BB61  B1 00     LDA (t_ptr),Y
    BB63  99 37 00  STA t_line,Y
    BB66  88        DEY
    BB67  10 F8     BPL LBB61
    BB69  A2 37     LDX #&37
    BB6B  A0 00     LDY #&00
    BB6D  20 F7 FF  JSR OSCLI
    BB70  4C 86 BB  JMP LBB86
; "TUNE",CR
    BB73  .db 54 55 4E 45 0D                                   ; TUNE.
; f2: REVEAL concealed text, and hold the page.
.key_f2_reveal
    BB78  A9 FF     LDA #&FF
    BB7A  85 09     STA t_reveal
    BB7C  20 DA B5  JSR draw_page
; f8: HOLD the page.
.key_f8_hold
    BB7F  A9 FF     LDA #&FF
    BB81  85 0B     STA t_hold
    BB83  4C 98 B3  JMP LB398
;------------------------------------------------------------------------------
; SPACE / ESCAPE: release the hold, redraw (MODE 7), rolling headers on.
;------------------------------------------------------------------------------
.LBB86
    BB86  A9 00     LDA #&00
    BB88  85 0B     STA t_hold
    BB8A  20 3A B7  JSR status_line_inline
    BB8D  .str '\x16\x07'
    BB8F  EA        NOP
    BB90  20 1B B4  JSR LB41B
    BB93  20 18 B5  JSR LB518
    BB96  20 A9 B6  JSR LB6A9
; SHIFT f2: conceal again, keeping the hold.
.key_sf2_conceal
    BB99  A9 00     LDA #&00
    BB9B  85 09     STA t_reveal
    BB9D  4C A8 B3  JMP LB3A8
;------------------------------------------------------------------------------
; f9: EXIT TO THE PREVIOUS LANGUAGE (page buffers released, previous filing system back).
;------------------------------------------------------------------------------
.key_f9_exit_language
    BBA0  20 08 BC  JSR LBC08
    BBA3  20 12 B5  JSR LB512
    BBA6  20 37 B7  JSR clear_status_inline
    BBA9  EA        NOP
    BBAA  20 85 B4  JSR LB485
    BBAD  4C D1 BB  JMP LBBD1
; "EXEC""",CR: *EXEC the first Telesoftware file on the page.
    BBB0  .db 45 58 45 43 22 22 0D                             ; EXEC"".
;------------------------------------------------------------------------------
; SHIFT f9: EXIT TO TELESOFT AND EXECUTE: a text window below the header row, then
; *EXEC "" so the program on the page is typed into the language, which is entered next.
;------------------------------------------------------------------------------
.key_sf9_telesoft
    BBB7  20 08 BC  JSR LBC08
    BBBA  20 3A B7  JSR status_line_inline
    BBBD  .str "\x16\x07\x1c\x00\x18'\x01"
    BBC4  EA        NOP
    BBC5  A9 0D     LDA #&0D
    BBC7  20 E3 FF  JSR OSASCI              ; VDU 13: carriage return
    BBCA  A2 B0     LDX #&B0
    BBCC  A0 BB     LDY #&BB
    BBCE  20 F7 FF  JSR OSCLI
;------------------------------------------------------------------------------
; Enter the previous language. If that was TFS itself (after BREAK in terminal mode),
; use BASIC instead when there is one.
;------------------------------------------------------------------------------
.LBBD1
    BBD1  20 1E BC  JSR LBC1E
    BBD4  A2 F4     LDX #&F4
    BBD6  86 5E     STX &5E
    BBD8  A2 00     LDX #&00
    BBDA  86 5F     STX &5F
    BBDC  A2 FF     LDX #&FF
    BBDE  86 60     STX &60
    BBE0  86 61     STX &61
    BBE2  A2 5E     LDX #&5E
    BBE4  A0 00     LDY #&00
    BBE6  A9 05     LDA #&05                ; read the current ROM number (&F4) from the I/O processor
    BBE8  20 F1 FF  JSR OSWORD              ; OSWORD &05: read I/O processor memory
    BBEB  A6 31     LDX t_prev_lang
    BBED  E4 62     CPX &62
    BBEF  D0 0F     BNE LBC00
    BBF1  A9 BB     LDA #&BB
    BBF3  A2 00     LDX #&00
    BBF5  A0 FF     LDY #&FF
    BBF7  20 F4 FF  JSR OSBYTE              ; OSBYTE &BB: read BASIC ROM number
    BBFA  E0 FF     CPX #&FF
    BBFC  D0 02     BNE LBC00
    BBFE  A6 31     LDX t_prev_lang
.LBC00
    BC00  A0 12     LDY #&12
    BC02  A9 8E     LDA #&8E
    BC04  4C F4 FF  JMP OSBYTE              ; OSBYTE &8E: enter language ROM X
.LBC07
    BC07  60        RTS
;------------------------------------------------------------------------------
; Leaving terminal mode: slot 0 back to its private-workspace buffer, other slots off.
;------------------------------------------------------------------------------
.LBC08
    BC08  A9 9E     LDA #&9E
    BC0A  85 0C     STA t_osw
    BC0C  20 F8 B3  JSR t_osword            ; OSWORD &7A &9E
    BC0F  A9 A2     LDA #&A2
    BC11  85 0C     STA t_osw
    BC13  20 F8 B3  JSR t_osword            ; OSWORD &7A &A2
    BC16  A9 A1     LDA #&A1
    BC18  85 0C     STA t_osw
    BC1A  20 F8 B3  JSR t_osword            ; OSWORD &7A &A1: reset requests
    BC1D  60        RTS
;------------------------------------------------------------------------------
; Keys back to normal: cursor editing, function keys as strings, cursor on.
;------------------------------------------------------------------------------
.LBC1E
    BC1E  A9 04     LDA #&04
    BC20  A2 00     LDX #&00
    BC22  A0 00     LDY #&00
    BC24  20 F4 FF  JSR OSBYTE
    BC27  A9 E1     LDA #&E1
    BC29  A2 01     LDX #&01
    BC2B  20 F4 FF  JSR OSBYTE              ; OSBYTE &E1: set base code for function keys
    BC2E  20 59 B5  JSR LB559
    BC31  60        RTS
;------------------------------------------------------------------------------
